insert into learning_evidences (id, dba_id, num, texto) select '8156af21-e4c8-5d7b-8b66-7e63c4d9fb79'::uuid, d.id, 1, 'Construye e interpreta representaciones pictóricas y diagramas para representar relaciones entre cantidades que se presentan en situaciones o fenómenos.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 1;
