insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('cf8a251a-a2da-5952-8671-2154155179d6'::uuid, 'multiple_choice', '¿En cuál el número dice CUÁNTOS hay?', '{"options":["Compré 5 manzanas","Vivo en el piso 3","Tomo el bus 20","Marco el teléfono 315"],"correctIndex":0,"ayuda":{"pista":"Busca el número que puedes contar con el dedo, uno por uno, hasta terminar.","pasos":["Un número no siempre cuenta cosas. A veces es un nombre: el bus 20, el piso 3, un teléfono.","Para saber si cuenta, pregúntate: ¿puedo señalarlos uno por uno y terminar?","Por ejemplo, en «5 manzanas» sí: señalas 1, 2, 3, 4, 5. En «el bus 20» no, porque no hay veinte buses."],"ojo":"El número de un bus, de un piso o de un teléfono es un nombre, no una cantidad."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('cf8a251a-a2da-5952-8671-2154155179d6'::uuid, 'multiple_choice', '¿En cuál el número dice CUÁNTOS hay?', '{"options":["Conté 7 perros","Vivo en la casa 7","Veo el canal 7","Llegué de 7º"],"correctIndex":0,"ayuda":{"pista":"Busca el número que puedes contar con el dedo, uno por uno, hasta terminar.","pasos":["Un número no siempre cuenta cosas. A veces es un nombre: el bus 20, el piso 3, un teléfono.","Para saber si cuenta, pregúntate: ¿puedo señalarlos uno por uno y terminar?","Por ejemplo, en «5 manzanas» sí: señalas 1, 2, 3, 4, 5. En «el bus 20» no, porque no hay veinte buses."],"ojo":"El número de un bus, de un piso o de un teléfono es un nombre, no una cantidad."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('cf8a251a-a2da-5952-8671-2154155179d6'::uuid, 'multiple_choice', '¿En cuál el número dice CUÁNTOS hay?', '{"options":["Serví 3 galletas","Subo al piso 3","Tomo la ruta 3","Uso la talla 3"],"correctIndex":0,"ayuda":{"pista":"Busca el número que puedes contar con el dedo, uno por uno, hasta terminar.","pasos":["Un número no siempre cuenta cosas. A veces es un nombre: el bus 20, el piso 3, un teléfono.","Para saber si cuenta, pregúntate: ¿puedo señalarlos uno por uno y terminar?","Por ejemplo, en «5 manzanas» sí: señalas 1, 2, 3, 4, 5. En «el bus 20» no, porque no hay veinte buses."],"ojo":"El número de un bus, de un piso o de un teléfono es un nombre, no una cantidad."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('cf8a251a-a2da-5952-8671-2154155179d6'::uuid, 'multiple_choice', '¿En cuál el número dice el ORDEN?', '{"options":["Llegó de segundo","Tiene dos perros","Mide dos metros","Vive en la casa dos"],"correctIndex":0,"ayuda":{"pista":"Busca el que dice en qué PUESTO va, no cuántos hay.","pasos":["Cuando el número dice el puesto, casi siempre se lee distinto: primero, segundo, quinto.","Por eso se escribe con esa bolita: 1º, 2º, 5º.","«Quedó de 5º» habla de UN niño y de su puesto. «Tiene 5 años» habla de una cantidad."],"ojo":"Ser el 5º no significa que haya cinco. Significa que hay cuatro adelante."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('cf8a251a-a2da-5952-8671-2154155179d6'::uuid, 'multiple_choice', '¿En cuál el número dice el ORDEN?', '{"options":["Quedó de quinto","Tiene cinco años","Pesa cinco kilos","Compró cinco panes"],"correctIndex":0,"ayuda":{"pista":"Busca el que dice en qué PUESTO va, no cuántos hay.","pasos":["Cuando el número dice el puesto, casi siempre se lee distinto: primero, segundo, quinto.","Por eso se escribe con esa bolita: 1º, 2º, 5º.","«Quedó de 5º» habla de UN niño y de su puesto. «Tiene 5 años» habla de una cantidad."],"ojo":"Ser el 5º no significa que haya cinco. Significa que hay cuatro adelante."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('cf8a251a-a2da-5952-8671-2154155179d6'::uuid, 'multiple_choice', '¿En cuál el número dice el ORDEN?', '{"options":["Es el primero de la fila","Tiene un hermano","Mide un metro","Cuesta un peso"],"correctIndex":0,"ayuda":{"pista":"Busca el que dice en qué PUESTO va, no cuántos hay.","pasos":["Cuando el número dice el puesto, casi siempre se lee distinto: primero, segundo, quinto.","Por eso se escribe con esa bolita: 1º, 2º, 5º.","«Quedó de 5º» habla de UN niño y de su puesto. «Tiene 5 años» habla de una cantidad."],"ojo":"Ser el 5º no significa que haya cinco. Significa que hay cuatro adelante."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('cf8a251a-a2da-5952-8671-2154155179d6'::uuid, 'multiple_choice', '¿En cuál el número es una MEDIDA?', '{"options":["Mide 3 metros","Tengo 3 primos","Vivo en el piso 3","Soy el número 3"],"correctIndex":0,"ayuda":{"pista":"Busca el número que viene con una unidad de medida: metros, kilos, minutos.","pasos":["Cuando el número mide, siempre lo acompaña una palabra que dice CON QUÉ se midió.","Metros para el largo, kilos para el peso, minutos para el tiempo.","Si el número va solo o con cosas contables (3 primos, 5 sillas), no está midiendo: está contando."],"ojo":"Busca la unidad. Sin unidad, el número no está midiendo."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('cf8a251a-a2da-5952-8671-2154155179d6'::uuid, 'multiple_choice', '¿En cuál el número es una MEDIDA?', '{"options":["Pesa 2 kilos","Tengo 2 gatos","Llegué de 2º","Vivo en el 2"],"correctIndex":0,"ayuda":{"pista":"Busca el número que viene con una unidad de medida: metros, kilos, minutos.","pasos":["Cuando el número mide, siempre lo acompaña una palabra que dice CON QUÉ se midió.","Metros para el largo, kilos para el peso, minutos para el tiempo.","Si el número va solo o con cosas contables (3 primos, 5 sillas), no está midiendo: está contando."],"ojo":"Busca la unidad. Sin unidad, el número no está midiendo."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('cf8a251a-a2da-5952-8671-2154155179d6'::uuid, 'multiple_choice', '¿En cuál el número es una MEDIDA?', '{"options":["Dura 5 minutos","Hay 5 sillas","Es el puesto 5","Tomo la ruta 5"],"correctIndex":0,"ayuda":{"pista":"Busca el número que viene con una unidad de medida: metros, kilos, minutos.","pasos":["Cuando el número mide, siempre lo acompaña una palabra que dice CON QUÉ se midió.","Metros para el largo, kilos para el peso, minutos para el tiempo.","Si el número va solo o con cosas contables (3 primos, 5 sillas), no está midiendo: está contando."],"ojo":"Busca la unidad. Sin unidad, el número no está midiendo."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('8156af21-e4c8-5d7b-8b66-7e63c4d9fb79'::uuid, 'multiple_choice', '¿Qué cuenta muestra el dibujo?', '{"options":["4 + 3","4 − 3","3 + 3","4 + 4"],"correctIndex":0,"visual":{"tipo":"juntar","icono":"🚗","primero":4,"segundo":3},"ayuda":{"pista":"El dibujo trae dos montones y el signo entre ellos. Cuenta cada montón por aparte.","pasos":["Los dos montones aparecen uno después del otro: primero uno, y después llega el segundo.","Cuenta cuántos hay en el primero y cuántos en el segundo, sin juntarlos todavía.","Como el segundo LLEGA, es una suma: se escribe el primero, el signo +, y el segundo."],"ojo":"Fíjate en el orden. Primero va el montón que ya estaba, no el que llegó."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('8156af21-e4c8-5d7b-8b66-7e63c4d9fb79'::uuid, 'multiple_choice', '¿Qué cuenta muestra el dibujo?', '{"options":["5 + 2","5 − 2","2 + 2","5 + 5"],"correctIndex":0,"visual":{"tipo":"juntar","icono":"🍎","primero":5,"segundo":2},"ayuda":{"pista":"El dibujo trae dos montones y el signo entre ellos. Cuenta cada montón por aparte.","pasos":["Los dos montones aparecen uno después del otro: primero uno, y después llega el segundo.","Cuenta cuántos hay en el primero y cuántos en el segundo, sin juntarlos todavía.","Como el segundo LLEGA, es una suma: se escribe el primero, el signo +, y el segundo."],"ojo":"Fíjate en el orden. Primero va el montón que ya estaba, no el que llegó."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('8156af21-e4c8-5d7b-8b66-7e63c4d9fb79'::uuid, 'multiple_choice', '¿Qué cuenta muestra el dibujo?', '{"options":["3 + 4","4 − 3","3 + 3","4 + 4"],"correctIndex":0,"visual":{"tipo":"juntar","icono":"🎈","primero":3,"segundo":4},"ayuda":{"pista":"El dibujo trae dos montones y el signo entre ellos. Cuenta cada montón por aparte.","pasos":["Los dos montones aparecen uno después del otro: primero uno, y después llega el segundo.","Cuenta cuántos hay en el primero y cuántos en el segundo, sin juntarlos todavía.","Como el segundo LLEGA, es una suma: se escribe el primero, el signo +, y el segundo."],"ojo":"Fíjate en el orden. Primero va el montón que ya estaba, no el que llegó."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('8156af21-e4c8-5d7b-8b66-7e63c4d9fb79'::uuid, 'multiple_choice', '¿Qué cuenta muestra el dibujo? Los grises ya se fueron.', '{"options":["7 − 2","7 + 2","5 − 2","7 − 5"],"correctIndex":0,"visual":{"tipo":"quitar","icono":"🍬","cantidad":7,"seVan":2},"ayuda":{"pista":"Cuenta TODOS los que ves, incluidos los apagados. Los apagados son los que se van.","pasos":["El dibujo muestra cuántos había: cuéntalos todos, también los que se apagaron.","Los apagados son los que se van, así que esos son los que se quitan.","Como se van, es una resta: primero cuántos había, después cuántos se van."],"ojo":"Si cuentas solo los encendidos te da lo que QUEDA, no la cuenta que hay que escribir."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('8156af21-e4c8-5d7b-8b66-7e63c4d9fb79'::uuid, 'multiple_choice', '¿Qué cuenta muestra el dibujo? Los grises ya se fueron.', '{"options":["6 − 3","6 + 3","3 − 3","6 − 2"],"correctIndex":0,"visual":{"tipo":"quitar","icono":"🍪","cantidad":6,"seVan":3},"ayuda":{"pista":"Cuenta TODOS los que ves, incluidos los apagados. Los apagados son los que se van.","pasos":["El dibujo muestra cuántos había: cuéntalos todos, también los que se apagaron.","Los apagados son los que se van, así que esos son los que se quitan.","Como se van, es una resta: primero cuántos había, después cuántos se van."],"ojo":"Si cuentas solo los encendidos te da lo que QUEDA, no la cuenta que hay que escribir."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('8156af21-e4c8-5d7b-8b66-7e63c4d9fb79'::uuid, 'multiple_choice', '¿Qué cuenta muestra el dibujo? Los grises ya se fueron.', '{"options":["5 − 1","5 + 1","4 − 1","5 − 4"],"correctIndex":0,"visual":{"tipo":"quitar","icono":"🎈","cantidad":5,"seVan":1},"ayuda":{"pista":"Cuenta TODOS los que ves, incluidos los apagados. Los apagados son los que se van.","pasos":["El dibujo muestra cuántos había: cuéntalos todos, también los que se apagaron.","Los apagados son los que se van, así que esos son los que se quitan.","Como se van, es una resta: primero cuántos había, después cuántos se van."],"ojo":"Si cuentas solo los encendidos te da lo que QUEDA, no la cuenta que hay que escribir."}}'::jsonb, 5);
