insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('4c3a34ea-1392-596d-84bc-cb6e882ddc01'::uuid, 'multiple_choice', 'Al bus se suben 3 niños. Para saber cuántos hay ahora:', '{"options":["Sumo","Resto","Cuento los que se bajaron","Vuelvo a contar desde uno"],"correctIndex":0,"ayuda":{"pista":"Fíjate si en la historia algo LLEGA o algo SE VA. Eso decide la operación.","pasos":["Lee la historia y busca el verbo: subirse, meter, llegar, regalar, echar.","Si algo llega o se agrega, la cantidad crece: se suma.","Si algo se va, se pierde o se come, la cantidad baja: se resta."],"ojo":"No todas las historias de este tema se suman. Lee qué pasó antes de decidir."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('4c3a34ea-1392-596d-84bc-cb6e882ddc01'::uuid, 'multiple_choice', 'Del bus se bajan 3 niños. Para saber cuántos quedan:', '{"options":["Resto","Sumo","Cuento los que se subieron","Cuento las sillas"],"correctIndex":0,"ayuda":{"pista":"Fíjate si en la historia algo LLEGA o algo SE VA. Eso decide la operación.","pasos":["Lee la historia y busca el verbo: subirse, meter, llegar, regalar, echar.","Si algo llega o se agrega, la cantidad crece: se suma.","Si algo se va, se pierde o se come, la cantidad baja: se resta."],"ojo":"No todas las historias de este tema se suman. Lee qué pasó antes de decidir."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('4c3a34ea-1392-596d-84bc-cb6e882ddc01'::uuid, 'multiple_choice', 'Metes 2 lápices más a la cartuchera. Para saber cuántos hay:', '{"options":["Sumo","Resto","Cuento los que metí","Cuento las cartucheras"],"correctIndex":0,"ayuda":{"pista":"Fíjate si en la historia algo LLEGA o algo SE VA. Eso decide la operación.","pasos":["Lee la historia y busca el verbo: subirse, meter, llegar, regalar, echar.","Si algo llega o se agrega, la cantidad crece: se suma.","Si algo se va, se pierde o se come, la cantidad baja: se resta."],"ojo":"No todas las historias de este tema se suman. Lee qué pasó antes de decidir."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('702dcfaa-5f7a-5abb-8ad6-d4ecf7f2fd3b'::uuid, 'multiple_choice', 'Dos jugadores tienen las camisetas 7 y 9. Sumarlas da:', '{"options":["Un dato que no sirve","El número de otro jugador","Los goles del equipo","La edad de los dos"],"correctIndex":0,"ayuda":{"pista":"Pregúntate si esos números cuentan cosas. Si son nombres, sumarlos no da nada.","pasos":["Una camiseta, una casa o un teléfono usan el número como NOMBRE: dicen cuál es, no cuántos hay.","Los nombres no se suman. Sumar la casa 20 y la casa 30 no da la casa 50 ni nada parecido.","Solo se pueden sumar los números que cuentan cosas del mismo tipo."],"ojo":"Que dos cosas tengan número no significa que se puedan sumar."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('702dcfaa-5f7a-5abb-8ad6-d4ecf7f2fd3b'::uuid, 'multiple_choice', 'Sumas el número de tu casa y el de tu bus. El total es:', '{"options":["Un dato que no sirve","Una dirección nueva","Una ruta nueva","Una edad cualquiera"],"correctIndex":0,"ayuda":{"pista":"Pregúntate si esos números cuentan cosas. Si son nombres, sumarlos no da nada.","pasos":["Una camiseta, una casa o un teléfono usan el número como NOMBRE: dicen cuál es, no cuántos hay.","Los nombres no se suman. Sumar la casa 20 y la casa 30 no da la casa 50 ni nada parecido.","Solo se pueden sumar los números que cuentan cosas del mismo tipo."],"ojo":"Que dos cosas tengan número no significa que se puedan sumar."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('702dcfaa-5f7a-5abb-8ad6-d4ecf7f2fd3b'::uuid, 'multiple_choice', 'Sumar dos números de teléfono sirve para:', '{"options":["No sirve para nada","Llamar a los dos","Saber quién llama","Hacer una llamada larga"],"correctIndex":0,"ayuda":{"pista":"Pregúntate si esos números cuentan cosas. Si son nombres, sumarlos no da nada.","pasos":["Una camiseta, una casa o un teléfono usan el número como NOMBRE: dicen cuál es, no cuántos hay.","Los nombres no se suman. Sumar la casa 20 y la casa 30 no da la casa 50 ni nada parecido.","Solo se pueden sumar los números que cuentan cosas del mismo tipo."],"ojo":"Que dos cosas tengan número no significa que se puedan sumar."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('702dcfaa-5f7a-5abb-8ad6-d4ecf7f2fd3b'::uuid, 'multiple_choice', 'Metiste 3 goles y después 2. Sumarlos te dice:', '{"options":["Cuántos goles metiste","En qué minuto los metiste","Cuánto duró el partido","Qué camiseta usas"],"correctIndex":0,"ayuda":{"pista":"Si los dos números cuentan lo MISMO, sumarlos tiene sentido y dice cuánto hay en total.","pasos":["Aquí los dos números cuentan lo mismo: goles y goles, monedas y monedas, personas y personas.","Cuando cuentan lo mismo, juntarlos sí significa algo: el total.","Por eso la respuesta habla de la cantidad, no del nombre ni de la hora ni del precio."],"ojo":"Suma solo cosas del mismo tipo. Tres goles y dos monedas no se suman."}}'::jsonb, 11);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('702dcfaa-5f7a-5abb-8ad6-d4ecf7f2fd3b'::uuid, 'multiple_choice', 'Tienes 4 monedas y te dan 2. Sumarlas te dice:', '{"options":["Cuánto dinero tienes","Cuánto pesa lo que tienes","De qué año son","Cuál moneda es"],"correctIndex":0,"ayuda":{"pista":"Si los dos números cuentan lo MISMO, sumarlos tiene sentido y dice cuánto hay en total.","pasos":["Aquí los dos números cuentan lo mismo: goles y goles, monedas y monedas, personas y personas.","Cuando cuentan lo mismo, juntarlos sí significa algo: el total.","Por eso la respuesta habla de la cantidad, no del nombre ni de la hora ni del precio."],"ojo":"Suma solo cosas del mismo tipo. Tres goles y dos monedas no se suman."}}'::jsonb, 11);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('702dcfaa-5f7a-5abb-8ad6-d4ecf7f2fd3b'::uuid, 'multiple_choice', 'En el bus van 8 personas y suben 3. Sumas para saber:', '{"options":["Cuántas personas van","Dónde se bajan las personas","Cuánto cuesta el pasaje","Qué ruta hace el bus"],"correctIndex":0,"ayuda":{"pista":"Si los dos números cuentan lo MISMO, sumarlos tiene sentido y dice cuánto hay en total.","pasos":["Aquí los dos números cuentan lo mismo: goles y goles, monedas y monedas, personas y personas.","Cuando cuentan lo mismo, juntarlos sí significa algo: el total.","Por eso la respuesta habla de la cantidad, no del nombre ni de la hora ni del precio."],"ojo":"Suma solo cosas del mismo tipo. Tres goles y dos monedas no se suman."}}'::jsonb, 11);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('4c3a34ea-1392-596d-84bc-cb6e882ddc01'::uuid, 'multiple_choice', 'De la caja se pierden 4 crayolas. Para saber cuántas quedan:', '{"options":["Resto","Sumo","Cuento las que se perdieron","Cuento las cajas"],"correctIndex":0,"ayuda":{"pista":"Fíjate si en la historia algo LLEGA o algo SE VA. Eso decide la operación.","pasos":["Busca el verbo de la historia: perderse, irse, comerse, bajarse… o llegar y echar.","Si algo desaparece, quedan menos: se resta.","Si algo aparece, hay más: se suma."],"ojo":"Ojo con esta: aquí también hay historias en las que la cantidad crece."}}'::jsonb, 12);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('4c3a34ea-1392-596d-84bc-cb6e882ddc01'::uuid, 'multiple_choice', 'Llegan 5 galletas más al paquete. Para saber cuántas hay:', '{"options":["Sumo","Resto","Cuento las que llegaron","Cuento los paquetes"],"correctIndex":0,"ayuda":{"pista":"Fíjate si en la historia algo LLEGA o algo SE VA. Eso decide la operación.","pasos":["Busca el verbo de la historia: perderse, irse, comerse, bajarse… o llegar y echar.","Si algo desaparece, quedan menos: se resta.","Si algo aparece, hay más: se suma."],"ojo":"Ojo con esta: aquí también hay historias en las que la cantidad crece."}}'::jsonb, 12);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('4c3a34ea-1392-596d-84bc-cb6e882ddc01'::uuid, 'multiple_choice', 'Se van 3 niños del salón. Para saber cuántos quedan:', '{"options":["Resto","Sumo","Cuento los que se fueron","Cuento los salones"],"correctIndex":0,"ayuda":{"pista":"Fíjate si en la historia algo LLEGA o algo SE VA. Eso decide la operación.","pasos":["Busca el verbo de la historia: perderse, irse, comerse, bajarse… o llegar y echar.","Si algo desaparece, quedan menos: se resta.","Si algo aparece, hay más: se suma."],"ojo":"Ojo con esta: aquí también hay historias en las que la cantidad crece."}}'::jsonb, 12);
