insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('d60bee53-6871-51fe-8ecc-f45af50d239a'::uuid, 'multiple_choice', 'Sin hacer la cuenta, 18 + 19 está cerca de:', '{"options":["40","20","60","80"],"correctIndex":0,"ayuda":{"pista":"Redondea cada número al diez más cercano y suma esos, que es mucho más fácil.","pasos":["Estimar no es hacer la cuenta exacta: es saber por dónde va a caer el resultado.","Mira cada número y pregúntate a qué diez está más cerca: 19 está pegado a 20, y 21 también.","Con los dieces la cuenta sale de cabeza, y el resultado de verdad queda ahí cerquita."],"ojo":"No hay que hacer la cuenta exacta. Si te pusiste a sumar de uno en uno, te pasaste de trabajo."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('d60bee53-6871-51fe-8ecc-f45af50d239a'::uuid, 'multiple_choice', 'Sin hacer la cuenta, 28 + 31 está cerca de:', '{"options":["60","30","90","15"],"correctIndex":0,"ayuda":{"pista":"Redondea cada número al diez más cercano y suma esos, que es mucho más fácil.","pasos":["Estimar no es hacer la cuenta exacta: es saber por dónde va a caer el resultado.","Mira cada número y pregúntate a qué diez está más cerca: 19 está pegado a 20, y 21 también.","Con los dieces la cuenta sale de cabeza, y el resultado de verdad queda ahí cerquita."],"ojo":"No hay que hacer la cuenta exacta. Si te pusiste a sumar de uno en uno, te pasaste de trabajo."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('d60bee53-6871-51fe-8ecc-f45af50d239a'::uuid, 'multiple_choice', 'Sin hacer la cuenta, 41 − 19 está cerca de:', '{"options":["20","60","40","5"],"correctIndex":0,"ayuda":{"pista":"Redondea cada número al diez más cercano y suma esos, que es mucho más fácil.","pasos":["Estimar no es hacer la cuenta exacta: es saber por dónde va a caer el resultado.","Mira cada número y pregúntate a qué diez está más cerca: 19 está pegado a 20, y 21 también.","Con los dieces la cuenta sale de cabeza, y el resultado de verdad queda ahí cerquita."],"ojo":"No hay que hacer la cuenta exacta. Si te pusiste a sumar de uno en uno, te pasaste de trabajo."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('d60bee53-6871-51fe-8ecc-f45af50d239a'::uuid, 'multiple_choice', '¿Cuántos dieces necesitas para armar 30?', '{"options":["3","30","13","10"],"correctIndex":0,"ayuda":{"pista":"Un diez es un montón de diez. Cuenta cuántos montones completos caben.","pasos":["Los números se arman con montones de diez y con unos sueltos.","Para saber cuántos dieces hay en 30, cuenta de 10 en 10: 10, 20, 30. Contaste 3.","Y al revés: 4 dieces y 2 unos se escriben poniendo primero los dieces y después los unos."],"ojo":"4 dieces y 2 unos no se escribe 402. El 4 ya está diciendo que son cuarenta."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('d60bee53-6871-51fe-8ecc-f45af50d239a'::uuid, 'multiple_choice', '¿Cuántos dieces necesitas para armar 50?', '{"options":["5","50","15","10"],"correctIndex":0,"ayuda":{"pista":"Un diez es un montón de diez. Cuenta cuántos montones completos caben.","pasos":["Los números se arman con montones de diez y con unos sueltos.","Para saber cuántos dieces hay en 30, cuenta de 10 en 10: 10, 20, 30. Contaste 3.","Y al revés: 4 dieces y 2 unos se escriben poniendo primero los dieces y después los unos."],"ojo":"4 dieces y 2 unos no se escribe 402. El 4 ya está diciendo que son cuarenta."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('d60bee53-6871-51fe-8ecc-f45af50d239a'::uuid, 'multiple_choice', 'Con 4 dieces y 2 unos armas el número:', '{"options":["42","24","6","402"],"correctIndex":0,"ayuda":{"pista":"Un diez es un montón de diez. Cuenta cuántos montones completos caben.","pasos":["Los números se arman con montones de diez y con unos sueltos.","Para saber cuántos dieces hay en 30, cuenta de 10 en 10: 10, 20, 30. Contaste 3.","Y al revés: 4 dieces y 2 unos se escriben poniendo primero los dieces y después los unos."],"ojo":"4 dieces y 2 unos no se escribe 402. El 4 ya está diciendo que son cuarenta."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('43dfc52e-0d1e-53e3-835f-f84ce8a4084a'::uuid, 'multiple_choice', 'En 2, 4, 6, 8... todos los números son:', '{"options":["Pares","Impares","Unos pares y otros no","Mayores que 10"],"correctIndex":0,"ayuda":{"pista":"Mira los números de la lista y busca qué tienen TODOS en común, no solo el primero.","pasos":["Una conjetura es darse cuenta de algo que se repite siempre.","Mira la lista entera, no un número suelto. ¿En qué terminan? ¿Se pueden repartir en dos montones iguales?","Los que se reparten en dos montones iguales son pares; los que dejan uno suelto son impares."],"ojo":"Que el primero cumpla no basta: la regla tiene que valer para todos."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('43dfc52e-0d1e-53e3-835f-f84ce8a4084a'::uuid, 'multiple_choice', 'En 1, 3, 5, 7... todos los números son:', '{"options":["Impares","Pares","Unos pares y otros no","Menores que 3"],"correctIndex":0,"ayuda":{"pista":"Mira los números de la lista y busca qué tienen TODOS en común, no solo el primero.","pasos":["Una conjetura es darse cuenta de algo que se repite siempre.","Mira la lista entera, no un número suelto. ¿En qué terminan? ¿Se pueden repartir en dos montones iguales?","Los que se reparten en dos montones iguales son pares; los que dejan uno suelto son impares."],"ojo":"Que el primero cumpla no basta: la regla tiene que valer para todos."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('43dfc52e-0d1e-53e3-835f-f84ce8a4084a'::uuid, 'multiple_choice', 'En 5, 10, 15, 20... todos terminan en:', '{"options":["5 o en 0","1 o en 2","3 o en 4","7 o en 9"],"correctIndex":0,"ayuda":{"pista":"Mira los números de la lista y busca qué tienen TODOS en común, no solo el primero.","pasos":["Una conjetura es darse cuenta de algo que se repite siempre.","Mira la lista entera, no un número suelto. ¿En qué terminan? ¿Se pueden repartir en dos montones iguales?","Los que se reparten en dos montones iguales son pares; los que dejan uno suelto son impares."],"ojo":"Que el primero cumpla no basta: la regla tiene que valer para todos."}}'::jsonb, 10);
