insert into learning_evidences (id, dba_id, num, texto) select '0edad46a-8c3a-5e02-8180-55800f8d6f7f'::uuid, d.id, 4, 'Emplea estrategias de cálculo como "el paso por el diez" para realizar adiciones o sustracciones.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 3;
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('789e36e3-1ccb-5f88-86e8-514a09551fed'::uuid, 'multiple_choice', '¿Qué número tiene 5 decenas y 2 unidades?', '{"options":["52","25","502","7"],"correctIndex":0,"visual":{"tipo":"decenas","decenas":5,"unidades":2},"ayuda":{"pista":"El número de dieces se escribe primero, y el de unos, de segundo.","pasos":["En un número de dos cifras, la de la izquierda dice cuántos DIECES hay.","La de la derecha dice cuántos UNOS sueltos quedan.","Por ejemplo, 5 decenas y 2 unidades se escribe 52: primero el 5, después el 2."],"ojo":"No se escriben pegados como 502, ni se suman como 5 + 2 = 7. El 5 vale cincuenta."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('789e36e3-1ccb-5f88-86e8-514a09551fed'::uuid, 'multiple_choice', '¿Qué número tiene 3 decenas y 6 unidades?', '{"options":["36","63","306","9"],"correctIndex":0,"visual":{"tipo":"decenas","decenas":3,"unidades":6},"ayuda":{"pista":"El número de dieces se escribe primero, y el de unos, de segundo.","pasos":["En un número de dos cifras, la de la izquierda dice cuántos DIECES hay.","La de la derecha dice cuántos UNOS sueltos quedan.","Por ejemplo, 5 decenas y 2 unidades se escribe 52: primero el 5, después el 2."],"ojo":"No se escriben pegados como 502, ni se suman como 5 + 2 = 7. El 5 vale cincuenta."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('789e36e3-1ccb-5f88-86e8-514a09551fed'::uuid, 'multiple_choice', '¿Qué número tiene 8 decenas y 1 unidad?', '{"options":["81","18","801","9"],"correctIndex":0,"visual":{"tipo":"decenas","decenas":8,"unidades":1},"ayuda":{"pista":"El número de dieces se escribe primero, y el de unos, de segundo.","pasos":["En un número de dos cifras, la de la izquierda dice cuántos DIECES hay.","La de la derecha dice cuántos UNOS sueltos quedan.","Por ejemplo, 5 decenas y 2 unidades se escribe 52: primero el 5, después el 2."],"ojo":"No se escriben pegados como 502, ni se suman como 5 + 2 = 7. El 5 vale cincuenta."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('789e36e3-1ccb-5f88-86e8-514a09551fed'::uuid, 'multiple_choice', 'El número 34 tiene:', '{"options":["3 decenas y 4 unidades","4 decenas y 3 unidades","3 decenas y 0 unidades","1 decena y 4 unidades"],"correctIndex":0,"visual":{"tipo":"decenas","decenas":3,"unidades":4},"ayuda":{"pista":"Lee el número de izquierda a derecha: la primera cifra son los dieces.","pasos":["Tapa la última cifra con el dedo. Lo que queda son los dieces.","Destapa: esa última cifra son los unos sueltos.","Por ejemplo, en 34: el 3 son 3 dieces (treinta) y el 4 son 4 unos."],"ojo":"El orden importa. 34 y 43 tienen las mismas cifras y no valen lo mismo."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('789e36e3-1ccb-5f88-86e8-514a09551fed'::uuid, 'multiple_choice', 'El número 47 tiene:', '{"options":["4 decenas y 7 unidades","7 decenas y 4 unidades","4 decenas y 0 unidades","1 decena y 7 unidades"],"correctIndex":0,"visual":{"tipo":"decenas","decenas":4,"unidades":7},"ayuda":{"pista":"Lee el número de izquierda a derecha: la primera cifra son los dieces.","pasos":["Tapa la última cifra con el dedo. Lo que queda son los dieces.","Destapa: esa última cifra son los unos sueltos.","Por ejemplo, en 34: el 3 son 3 dieces (treinta) y el 4 son 4 unos."],"ojo":"El orden importa. 34 y 43 tienen las mismas cifras y no valen lo mismo."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('789e36e3-1ccb-5f88-86e8-514a09551fed'::uuid, 'multiple_choice', 'El número 29 tiene:', '{"options":["2 decenas y 9 unidades","9 decenas y 2 unidades","2 decenas y 0 unidades","1 decena y 9 unidades"],"correctIndex":0,"visual":{"tipo":"decenas","decenas":2,"unidades":9},"ayuda":{"pista":"Lee el número de izquierda a derecha: la primera cifra son los dieces.","pasos":["Tapa la última cifra con el dedo. Lo que queda son los dieces.","Destapa: esa última cifra son los unos sueltos.","Por ejemplo, en 34: el 3 son 3 dieces (treinta) y el 4 son 4 unos."],"ojo":"El orden importa. 34 y 43 tienen las mismas cifras y no valen lo mismo."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('789e36e3-1ccb-5f88-86e8-514a09551fed'::uuid, 'multiple_choice', 'El número 70 tiene:', '{"options":["7 decenas y 0 unidades","0 decenas y 7 unidades","7 decenas y 7 unidades","1 decena y 7 unidades"],"correctIndex":0,"visual":{"tipo":"decenas","decenas":7,"unidades":0},"ayuda":{"pista":"Un cero en los unos quiere decir que no sobró ninguno suelto.","pasos":["Los números que terminan en 0 son dieces exactos: no quedó ningún uno suelto.","Por ejemplo, 70 son 7 dieces y 0 unos.","Por eso se cuentan de 10 en 10: 10, 20, 30… y siempre caen justo."],"ojo":"70 no son 7 unidades. El 0 está diciendo que el 7 son dieces."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('789e36e3-1ccb-5f88-86e8-514a09551fed'::uuid, 'multiple_choice', 'El número 50 tiene:', '{"options":["5 decenas y 0 unidades","0 decenas y 5 unidades","5 decenas y 5 unidades","1 decena y 5 unidades"],"correctIndex":0,"visual":{"tipo":"decenas","decenas":5,"unidades":0},"ayuda":{"pista":"Un cero en los unos quiere decir que no sobró ninguno suelto.","pasos":["Los números que terminan en 0 son dieces exactos: no quedó ningún uno suelto.","Por ejemplo, 70 son 7 dieces y 0 unos.","Por eso se cuentan de 10 en 10: 10, 20, 30… y siempre caen justo."],"ojo":"70 no son 7 unidades. El 0 está diciendo que el 7 son dieces."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('789e36e3-1ccb-5f88-86e8-514a09551fed'::uuid, 'multiple_choice', 'El número 90 tiene:', '{"options":["9 decenas y 0 unidades","0 decenas y 9 unidades","9 decenas y 9 unidades","1 decena y 9 unidades"],"correctIndex":0,"visual":{"tipo":"decenas","decenas":9,"unidades":0},"ayuda":{"pista":"Un cero en los unos quiere decir que no sobró ninguno suelto.","pasos":["Los números que terminan en 0 son dieces exactos: no quedó ningún uno suelto.","Por ejemplo, 70 son 7 dieces y 0 unos.","Por eso se cuentan de 10 en 10: 10, 20, 30… y siempre caen justo."],"ojo":"70 no son 7 unidades. El 0 está diciendo que el 7 son dieces."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('789e36e3-1ccb-5f88-86e8-514a09551fed'::uuid, 'multiple_choice', 'Armas 47 con fichas de 10 y de 1. ¿Cuál usa MENOS fichas?', '{"options":["4 de diez y 7 de uno","3 de diez y 17 de uno","2 de diez y 27 de uno","47 de uno"],"correctIndex":0,"ayuda":{"pista":"Usa la mayor cantidad posible de fichas de diez. Cada una te ahorra diez de uno.","pasos":["El mismo número se puede armar de muchas maneras, y todas valen lo mismo.","Pero no todas usan la misma cantidad de fichas: mientras más de diez uses, menos fichas necesitas.","Por eso la respuesta es la que aprovecha todos los dieces que caben, y deja solo los unos sueltos."],"ojo":"Todas las opciones arman el mismo número. La pregunta no es cuánto, es con cuántas fichas."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('789e36e3-1ccb-5f88-86e8-514a09551fed'::uuid, 'multiple_choice', 'Armas 35 con fichas de 10 y de 1. ¿Cuál usa MENOS fichas?', '{"options":["3 de diez y 5 de uno","2 de diez y 15 de uno","1 de diez y 25 de uno","35 de uno"],"correctIndex":0,"ayuda":{"pista":"Usa la mayor cantidad posible de fichas de diez. Cada una te ahorra diez de uno.","pasos":["El mismo número se puede armar de muchas maneras, y todas valen lo mismo.","Pero no todas usan la misma cantidad de fichas: mientras más de diez uses, menos fichas necesitas.","Por eso la respuesta es la que aprovecha todos los dieces que caben, y deja solo los unos sueltos."],"ojo":"Todas las opciones arman el mismo número. La pregunta no es cuánto, es con cuántas fichas."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('789e36e3-1ccb-5f88-86e8-514a09551fed'::uuid, 'multiple_choice', 'Armas 52 con fichas de 10 y de 1. ¿Cuál usa MENOS fichas?', '{"options":["5 de diez y 2 de uno","4 de diez y 12 de uno","3 de diez y 22 de uno","52 de uno"],"correctIndex":0,"ayuda":{"pista":"Usa la mayor cantidad posible de fichas de diez. Cada una te ahorra diez de uno.","pasos":["El mismo número se puede armar de muchas maneras, y todas valen lo mismo.","Pero no todas usan la misma cantidad de fichas: mientras más de diez uses, menos fichas necesitas.","Por eso la respuesta es la que aprovecha todos los dieces que caben, y deja solo los unos sueltos."],"ojo":"Todas las opciones arman el mismo número. La pregunta no es cuánto, es con cuántas fichas."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('a626dde2-56dc-569b-8ac7-378faf24a85b'::uuid, 'multiple_choice', '¿Cuál pareja suma 10?', '{"options":["6 y 4","6 y 3","5 y 6","8 y 3"],"correctIndex":0,"ayuda":{"pista":"Prueba cada pareja: cuenta desde el primer número hasta ver si llegas justo a 10.","pasos":["Las parejas que suman 10 hay que aprendérselas, porque se usan todo el tiempo.","Son: 1 y 9, 2 y 8, 3 y 7, 4 y 6, y 5 con 5.","Fíjate que cuando una sube, la otra baja: si tienes más de una, necesitas menos de la otra."],"ojo":"Revisa todas las parejas antes de elegir: varias se parecen y solo una da justo 10."}}'::jsonb, 5);
