insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('6ebb1735-ccda-5f30-8cbd-f4f6f79be518'::uuid, 'multiple_choice', '¿Cuál grupo tiene MÁS estrellas?', '{"options":["El grupo 1","El grupo 2","El grupo 3","Todos tienen igual"],"correctIndex":0,"visual":{"tipo":"comparar","icono":"⭐","lados":[{"etiqueta":"Grupo 1","cantidad":8},{"etiqueta":"Grupo 2","cantidad":5},{"etiqueta":"Grupo 3","cantidad":3}]},"ayuda":{"pista":"Todas las filas arrancan en el mismo sitio: la que llega más lejos es la que tiene más.","pasos":["Los tres grupos tienen el mismo dibujo y empiezan alineados, así que se pueden comparar de un vistazo.","La fila que llega más lejos es la que tiene más.","Si no se ve claro, cuenta cada fila tocando los dibujos con el dedo."],"ojo":"Fíjate en el número de la fila, no en cuál grupo está de primero."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('6ebb1735-ccda-5f30-8cbd-f4f6f79be518'::uuid, 'multiple_choice', '¿Cuál grupo tiene MÁS bolas?', '{"options":["El grupo 2","El grupo 1","El grupo 3","Todos tienen igual"],"correctIndex":0,"visual":{"tipo":"comparar","icono":"🔵","lados":[{"etiqueta":"Grupo 1","cantidad":4},{"etiqueta":"Grupo 2","cantidad":7},{"etiqueta":"Grupo 3","cantidad":2}]},"ayuda":{"pista":"Todas las filas arrancan en el mismo sitio: la que llega más lejos es la que tiene más.","pasos":["Los tres grupos tienen el mismo dibujo y empiezan alineados, así que se pueden comparar de un vistazo.","La fila que llega más lejos es la que tiene más.","Si no se ve claro, cuenta cada fila tocando los dibujos con el dedo."],"ojo":"Fíjate en el número de la fila, no en cuál grupo está de primero."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('6ebb1735-ccda-5f30-8cbd-f4f6f79be518'::uuid, 'multiple_choice', '¿Cuál grupo tiene MÁS fichas?', '{"options":["El grupo 3","El grupo 1","El grupo 2","Todos tienen igual"],"correctIndex":0,"visual":{"tipo":"comparar","icono":"🟦","lados":[{"etiqueta":"Grupo 1","cantidad":3},{"etiqueta":"Grupo 2","cantidad":4},{"etiqueta":"Grupo 3","cantidad":9}]},"ayuda":{"pista":"Todas las filas arrancan en el mismo sitio: la que llega más lejos es la que tiene más.","pasos":["Los tres grupos tienen el mismo dibujo y empiezan alineados, así que se pueden comparar de un vistazo.","La fila que llega más lejos es la que tiene más.","Si no se ve claro, cuenta cada fila tocando los dibujos con el dedo."],"ojo":"Fíjate en el número de la fila, no en cuál grupo está de primero."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('6ebb1735-ccda-5f30-8cbd-f4f6f79be518'::uuid, 'multiple_choice', '¿Cuál grupo tiene MENOS?', '{"options":["2 flores","5 flores","7 flores","9 flores"],"correctIndex":0,"ayuda":{"pista":"El que tiene MENOS es el número más pequeño. Compáralos de a dos.","pasos":["Como todos los grupos son de lo mismo, se comparan los números directamente.","Ve de a dos y quédate siempre con el más pequeño.","El que gane todas las comparaciones es el que tiene menos."],"ojo":"Aquí piden MENOS. Contestar con el número más grande es el error de siempre."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('6ebb1735-ccda-5f30-8cbd-f4f6f79be518'::uuid, 'multiple_choice', '¿Cuál grupo tiene MENOS?', '{"options":["3 lápices","6 lápices","8 lápices","11 lápices"],"correctIndex":0,"ayuda":{"pista":"El que tiene MENOS es el número más pequeño. Compáralos de a dos.","pasos":["Como todos los grupos son de lo mismo, se comparan los números directamente.","Ve de a dos y quédate siempre con el más pequeño.","El que gane todas las comparaciones es el que tiene menos."],"ojo":"Aquí piden MENOS. Contestar con el número más grande es el error de siempre."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('6ebb1735-ccda-5f30-8cbd-f4f6f79be518'::uuid, 'multiple_choice', '¿Cuál grupo tiene MENOS?', '{"options":["1 galleta","4 galletas","7 galletas","10 galletas"],"correctIndex":0,"ayuda":{"pista":"El que tiene MENOS es el número más pequeño. Compáralos de a dos.","pasos":["Como todos los grupos son de lo mismo, se comparan los números directamente.","Ve de a dos y quédate siempre con el más pequeño.","El que gane todas las comparaciones es el que tiene menos."],"ojo":"Aquí piden MENOS. Contestar con el número más grande es el error de siempre."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('f1d43f9c-44a0-5c5a-82c2-3d083da1e2cb'::uuid, 'multiple_choice', '¿Qué se puede medir de una cuerda?', '{"options":["Su largo","Su color","Su nombre","Su dueño"],"correctIndex":0,"ayuda":{"pista":"Se puede medir lo que tiene MÁS o MENOS. Lo que solo tiene un nombre, no.","pasos":["Medir es poner un número: 3 metros, 2 kilos, 5 minutos.","Pregúntate: ¿esto puede tener más o menos? El largo sí, el peso sí, la duración sí.","El nombre y el color no: una cuerda no tiene «más nombre» que otra."],"ojo":"Que algo se pueda ver o decir no significa que se pueda medir."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('f1d43f9c-44a0-5c5a-82c2-3d083da1e2cb'::uuid, 'multiple_choice', '¿Qué se puede medir de una piedra?', '{"options":["Su peso","Su nombre","Si es bonita","Su sabor"],"correctIndex":0,"ayuda":{"pista":"Se puede medir lo que tiene MÁS o MENOS. Lo que solo tiene un nombre, no.","pasos":["Medir es poner un número: 3 metros, 2 kilos, 5 minutos.","Pregúntate: ¿esto puede tener más o menos? El largo sí, el peso sí, la duración sí.","El nombre y el color no: una cuerda no tiene «más nombre» que otra."],"ojo":"Que algo se pueda ver o decir no significa que se pueda medir."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('f1d43f9c-44a0-5c5a-82c2-3d083da1e2cb'::uuid, 'multiple_choice', '¿Qué se puede medir de una canción?', '{"options":["Cuánto dura","Su color","Su peso","Su sabor"],"correctIndex":0,"ayuda":{"pista":"Se puede medir lo que tiene MÁS o MENOS. Lo que solo tiene un nombre, no.","pasos":["Medir es poner un número: 3 metros, 2 kilos, 5 minutos.","Pregúntate: ¿esto puede tener más o menos? El largo sí, el peso sí, la duración sí.","El nombre y el color no: una cuerda no tiene «más nombre» que otra."],"ojo":"Que algo se pueda ver o decir no significa que se pueda medir."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('f1d43f9c-44a0-5c5a-82c2-3d083da1e2cb'::uuid, 'multiple_choice', '¿Qué se puede medir de una caja de jugo?', '{"options":["Cuánto le cabe","De qué marca es","De qué sabor es","Qué dibujo tiene"],"correctIndex":0,"ayuda":{"pista":"Cuando algo es un recipiente, lo que se mide es CUÁNTO LE CABE adentro.","pasos":["Las cosas huecas —una botella, una olla, un salón— guardan otras cosas adentro.","Eso que les cabe se llama capacidad, y se mide llenándolas.","Se mide con lo que quepa: vasos de agua, pocillos de arroz, niños en un salón."],"ojo":"La marca, el color o el dibujo del envase no son cosas que se midan."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('f1d43f9c-44a0-5c5a-82c2-3d083da1e2cb'::uuid, 'multiple_choice', '¿Qué se puede medir de una botella?', '{"options":["Cuánta agua le cabe","De qué marca es","De qué color es","Cómo es la tapa"],"correctIndex":0,"ayuda":{"pista":"Cuando algo es un recipiente, lo que se mide es CUÁNTO LE CABE adentro.","pasos":["Las cosas huecas —una botella, una olla, un salón— guardan otras cosas adentro.","Eso que les cabe se llama capacidad, y se mide llenándolas.","Se mide con lo que quepa: vasos de agua, pocillos de arroz, niños en un salón."],"ojo":"La marca, el color o el dibujo del envase no son cosas que se midan."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('f1d43f9c-44a0-5c5a-82c2-3d083da1e2cb'::uuid, 'multiple_choice', '¿Qué se puede medir de un salón?', '{"options":["Cuántos niños caben","Cómo se llama el salón","De qué color es","Quién es el profe"],"correctIndex":0,"ayuda":{"pista":"Cuando algo es un recipiente, lo que se mide es CUÁNTO LE CABE adentro.","pasos":["Las cosas huecas —una botella, una olla, un salón— guardan otras cosas adentro.","Eso que les cabe se llama capacidad, y se mide llenándolas.","Se mide con lo que quepa: vasos de agua, pocillos de arroz, niños en un salón."],"ojo":"La marca, el color o el dibujo del envase no son cosas que se midan."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('3c021705-3f65-5804-871c-e45d6b4e2741'::uuid, 'multiple_choice', '¿Cuál es el MÁS CORTO?', '{"options":["Un clip","Un lápiz","Una regla","Una escoba"],"correctIndex":0,"ayuda":{"pista":"Imagínalos todos juntos, uno al lado del otro. Ahí se ve cuál sobresale.","pasos":["Para comparar el largo o el alto, imagina los objetos puestos uno al lado del otro.","Ordénalos de mentiras, del más pequeño al más grande.","El que te piden es el que queda en una de las dos puntas de esa fila."],"ojo":"Fíjate bien si piden el MÁS o el MENOS antes de contestar."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('3c021705-3f65-5804-871c-e45d6b4e2741'::uuid, 'multiple_choice', '¿Cuál es el MÁS LARGO?', '{"options":["Un bus","Una bicicleta","Un patín","Un zapato"],"correctIndex":0,"ayuda":{"pista":"Imagínalos todos juntos, uno al lado del otro. Ahí se ve cuál sobresale.","pasos":["Para comparar el largo o el alto, imagina los objetos puestos uno al lado del otro.","Ordénalos de mentiras, del más pequeño al más grande.","El que te piden es el que queda en una de las dos puntas de esa fila."],"ojo":"Fíjate bien si piden el MÁS o el MENOS antes de contestar."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('3c021705-3f65-5804-871c-e45d6b4e2741'::uuid, 'multiple_choice', '¿Cuál es el MÁS ALTO?', '{"options":["Un árbol","Una silla","Un perro","Una hormiga"],"correctIndex":0,"ayuda":{"pista":"Imagínalos todos juntos, uno al lado del otro. Ahí se ve cuál sobresale.","pasos":["Para comparar el largo o el alto, imagina los objetos puestos uno al lado del otro.","Ordénalos de mentiras, del más pequeño al más grande.","El que te piden es el que queda en una de las dos puntas de esa fila."],"ojo":"Fíjate bien si piden el MÁS o el MENOS antes de contestar."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('3c021705-3f65-5804-871c-e45d6b4e2741'::uuid, 'multiple_choice', '¿Cuál pesa MÁS?', '{"options":["Un balde de agua","Un vaso de agua","Una cuchara de agua","Una gota de agua"],"correctIndex":0,"ayuda":{"pista":"Imagina que los cargas en las manos. El que te hunde el brazo pesa más.","pasos":["El peso no se ve: se siente. Imagina que levantas cada cosa.","Casi siempre, si es de lo mismo, la más grande pesa más: un balde de agua pesa más que un vaso de agua.","Ordénalos de mentiras del más liviano al más pesado y elige la punta que te piden."],"ojo":"Grande no siempre es pesado, pero cuando son de lo MISMO, sí."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('3c021705-3f65-5804-871c-e45d6b4e2741'::uuid, 'multiple_choice', '¿Cuál pesa MÁS?', '{"options":["Un bulto de papas","Una bolsa de papas","Una papa","Un pedazo de papa"],"correctIndex":0,"ayuda":{"pista":"Imagina que los cargas en las manos. El que te hunde el brazo pesa más.","pasos":["El peso no se ve: se siente. Imagina que levantas cada cosa.","Casi siempre, si es de lo mismo, la más grande pesa más: un balde de agua pesa más que un vaso de agua.","Ordénalos de mentiras del más liviano al más pesado y elige la punta que te piden."],"ojo":"Grande no siempre es pesado, pero cuando son de lo MISMO, sí."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('3c021705-3f65-5804-871c-e45d6b4e2741'::uuid, 'multiple_choice', '¿Cuál pesa MENOS?', '{"options":["Una hoja de papel","Un cuaderno","Un libro","Una maleta"],"correctIndex":0,"ayuda":{"pista":"Imagina que los cargas en las manos. El que te hunde el brazo pesa más.","pasos":["El peso no se ve: se siente. Imagina que levantas cada cosa.","Casi siempre, si es de lo mismo, la más grande pesa más: un balde de agua pesa más que un vaso de agua.","Ordénalos de mentiras del más liviano al más pesado y elige la punta que te piden."],"ojo":"Grande no siempre es pesado, pero cuando son de lo MISMO, sí."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('3c021705-3f65-5804-871c-e45d6b4e2741'::uuid, 'multiple_choice', 'Cajas iguales con algodón, arroz y plastilina. ¿Cuál pesa más?', '{"options":["La de plastilina","La de algodón","La de arroz","Todas pesan igual"],"correctIndex":0,"ayuda":{"pista":"Grande no es lo mismo que pesado. Piensa de qué está hecha cada una.","pasos":["Dos cosas del mismo tamaño pueden pesar muy distinto, según de qué estén hechas.","El algodón y el icopor son muy livianos: ocupan mucho y casi no pesan.","La plastilina, el arroz y el metal son pesados: en poquito espacio hay mucho peso."],"ojo":"Una caja chiquita puede pesar más que una grande. El tamaño no decide el peso."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('3c021705-3f65-5804-871c-e45d6b4e2741'::uuid, 'multiple_choice', 'Caja chiquita de plastilina o caja grande de algodón. ¿Cuál pesa más?', '{"options":["La chiquita de plastilina","La grande de algodón","Las dos cajas pesan igual","No se puede saber"],"correctIndex":0,"ayuda":{"pista":"Grande no es lo mismo que pesado. Piensa de qué está hecha cada una.","pasos":["Dos cosas del mismo tamaño pueden pesar muy distinto, según de qué estén hechas.","El algodón y el icopor son muy livianos: ocupan mucho y casi no pesan.","La plastilina, el arroz y el metal son pesados: en poquito espacio hay mucho peso."],"ojo":"Una caja chiquita puede pesar más que una grande. El tamaño no decide el peso."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('3c021705-3f65-5804-871c-e45d6b4e2741'::uuid, 'multiple_choice', 'Bola de icopor grande o bola de metal pequeña. ¿Cuál pesa más?', '{"options":["La bola de metal","La bola de icopor","Las dos bolas pesan igual","No se puede saber"],"correctIndex":0,"ayuda":{"pista":"Grande no es lo mismo que pesado. Piensa de qué está hecha cada una.","pasos":["Dos cosas del mismo tamaño pueden pesar muy distinto, según de qué estén hechas.","El algodón y el icopor son muy livianos: ocupan mucho y casi no pesan.","La plastilina, el arroz y el metal son pesados: en poquito espacio hay mucho peso."],"ojo":"Una caja chiquita puede pesar más que una grande. El tamaño no decide el peso."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('61d76b02-fa79-5e7b-8706-9cb825a7018f'::uuid, 'multiple_choice', '¿Con qué sabes cuánto PESA una fruta?', '{"options":["Con una balanza","Con una regla","Con un reloj","Con un vaso"],"correctIndex":0,"ayuda":{"pista":"Cada instrumento sirve para una sola cosa. Fíjate qué te están pidiendo medir.","pasos":["La balanza pesa. El metro y la regla miden el largo. El reloj mide el tiempo.","Lee la pregunta y subraya con el dedo qué piden: ¿pesa, mide o dura?","Elige el instrumento que sirve para eso."],"ojo":"Con una regla no se puede pesar, por grande que sea la regla."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('61d76b02-fa79-5e7b-8706-9cb825a7018f'::uuid, 'multiple_choice', '¿Con qué sabes cuánto PESA un bulto?', '{"options":["Con una balanza","Con un metro","Con un reloj","Con una jarra"],"correctIndex":0,"ayuda":{"pista":"Cada instrumento sirve para una sola cosa. Fíjate qué te están pidiendo medir.","pasos":["La balanza pesa. El metro y la regla miden el largo. El reloj mide el tiempo.","Lee la pregunta y subraya con el dedo qué piden: ¿pesa, mide o dura?","Elige el instrumento que sirve para eso."],"ojo":"Con una regla no se puede pesar, por grande que sea la regla."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('61d76b02-fa79-5e7b-8706-9cb825a7018f'::uuid, 'multiple_choice', '¿Con qué sabes cuánto MIDE una mesa?', '{"options":["Con un metro","Con una balanza","Con un reloj","Con un vaso"],"correctIndex":0,"ayuda":{"pista":"Cada instrumento sirve para una sola cosa. Fíjate qué te están pidiendo medir.","pasos":["La balanza pesa. El metro y la regla miden el largo. El reloj mide el tiempo.","Lee la pregunta y subraya con el dedo qué piden: ¿pesa, mide o dura?","Elige el instrumento que sirve para eso."],"ojo":"Con una regla no se puede pesar, por grande que sea la regla."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('61d76b02-fa79-5e7b-8706-9cb825a7018f'::uuid, 'multiple_choice', '¿Con qué sabes cuánto DURA un juego?', '{"options":["Con un reloj","Con una regla","Con una balanza","Con un vaso"],"correctIndex":0,"ayuda":{"pista":"Cuando la pregunta dice CUÁNTO DURA o QUÉ DÍA, lo que se mide es tiempo.","pasos":["El tiempo corto —un juego, una clase— se mide con un reloj.","El tiempo largo —los días, las semanas— se mira en un calendario.","Ni la balanza ni la regla sirven: el tiempo no pesa ni tiene largo."],"ojo":"Un reloj y un calendario miden los dos el tiempo, pero uno corto y el otro largo."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('61d76b02-fa79-5e7b-8706-9cb825a7018f'::uuid, 'multiple_choice', '¿Con qué sabes cuánto DURA una clase?', '{"options":["Con un reloj","Con un metro","Con una balanza","Con una jarra"],"correctIndex":0,"ayuda":{"pista":"Cuando la pregunta dice CUÁNTO DURA o QUÉ DÍA, lo que se mide es tiempo.","pasos":["El tiempo corto —un juego, una clase— se mide con un reloj.","El tiempo largo —los días, las semanas— se mira en un calendario.","Ni la balanza ni la regla sirven: el tiempo no pesa ni tiene largo."],"ojo":"Un reloj y un calendario miden los dos el tiempo, pero uno corto y el otro largo."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('61d76b02-fa79-5e7b-8706-9cb825a7018f'::uuid, 'multiple_choice', '¿Con qué sabes qué día es hoy?', '{"options":["Con un calendario","Con una regla","Con una balanza","Con un vaso"],"correctIndex":0,"ayuda":{"pista":"Cuando la pregunta dice CUÁNTO DURA o QUÉ DÍA, lo que se mide es tiempo.","pasos":["El tiempo corto —un juego, una clase— se mide con un reloj.","El tiempo largo —los días, las semanas— se mira en un calendario.","Ni la balanza ni la regla sirven: el tiempo no pesa ni tiene largo."],"ojo":"Un reloj y un calendario miden los dos el tiempo, pero uno corto y el otro largo."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('61d76b02-fa79-5e7b-8706-9cb825a7018f'::uuid, 'multiple_choice', '¿Con qué sabes cuánta agua CABE en una jarra?', '{"options":["Con un vaso","Con una regla","Con un reloj","Con una balanza"],"correctIndex":0,"ayuda":{"pista":"Para saber cuánto CABE, se llena con algo más pequeño y se cuenta cuántos entraron.","pasos":["La capacidad se mide llenando: vasos para el agua, pocillos para el arroz.","Se cuenta cuántos vasos o pocillos entraron, y ese número es la medida.","Cuidado: si la pregunta cambia y pide el LARGO, entonces sí es una regla."],"ojo":"Una de estas tres preguntas no es de capacidad. Léela bien antes de contestar."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('61d76b02-fa79-5e7b-8706-9cb825a7018f'::uuid, 'multiple_choice', '¿Con qué sabes cuánto arroz CABE en una olla?', '{"options":["Con un pocillo","Con una regla","Con un reloj","Con un metro"],"correctIndex":0,"ayuda":{"pista":"Para saber cuánto CABE, se llena con algo más pequeño y se cuenta cuántos entraron.","pasos":["La capacidad se mide llenando: vasos para el agua, pocillos para el arroz.","Se cuenta cuántos vasos o pocillos entraron, y ese número es la medida.","Cuidado: si la pregunta cambia y pide el LARGO, entonces sí es una regla."],"ojo":"Una de estas tres preguntas no es de capacidad. Léela bien antes de contestar."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('61d76b02-fa79-5e7b-8706-9cb825a7018f'::uuid, 'multiple_choice', '¿Con qué mides el largo de un cuaderno?', '{"options":["Con una regla","Con un reloj","Con una balanza","Con un pocillo"],"correctIndex":0,"ayuda":{"pista":"Para saber cuánto CABE, se llena con algo más pequeño y se cuenta cuántos entraron.","pasos":["La capacidad se mide llenando: vasos para el agua, pocillos para el arroz.","Se cuenta cuántos vasos o pocillos entraron, y ese número es la medida.","Cuidado: si la pregunta cambia y pide el LARGO, entonces sí es una regla."],"ojo":"Una de estas tres preguntas no es de capacidad. Léela bien antes de contestar."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('3c021705-3f65-5804-871c-e45d6b4e2741'::uuid, 'multiple_choice', '¿Quién caminó MÁS?', '{"options":["El que dio 30 pasos","El que dio 20 pasos","El que dio 10 pasos","El que dio 5 pasos"],"correctIndex":0,"ayuda":{"pista":"Si los dos midieron con lo mismo, el que dio más pasos recorrió más.","pasos":["Cuando se mide con pasos o baldosas, el número dice cuánto se recorrió.","Como la unidad es la misma para todos, se pueden comparar los números directamente.","Más pasos es más camino; menos pasos es menos camino."],"ojo":"Esto solo vale si los pasos son iguales. Con pasos distintos, los números no se pueden comparar."}}'::jsonb, 11);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('3c021705-3f65-5804-871c-e45d6b4e2741'::uuid, 'multiple_choice', '¿Quién caminó MENOS?', '{"options":["El que dio 8 pasos","El que dio 15 pasos","El que dio 22 pasos","El que dio 40 pasos"],"correctIndex":0,"ayuda":{"pista":"Si los dos midieron con lo mismo, el que dio más pasos recorrió más.","pasos":["Cuando se mide con pasos o baldosas, el número dice cuánto se recorrió.","Como la unidad es la misma para todos, se pueden comparar los números directamente.","Más pasos es más camino; menos pasos es menos camino."],"ojo":"Esto solo vale si los pasos son iguales. Con pasos distintos, los números no se pueden comparar."}}'::jsonb, 11);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('3c021705-3f65-5804-871c-e45d6b4e2741'::uuid, 'multiple_choice', '¿Cuál recorrido es MÁS LARGO?', '{"options":["25 baldosas","18 baldosas","12 baldosas","6 baldosas"],"correctIndex":0,"ayuda":{"pista":"Si los dos midieron con lo mismo, el que dio más pasos recorrió más.","pasos":["Cuando se mide con pasos o baldosas, el número dice cuánto se recorrió.","Como la unidad es la misma para todos, se pueden comparar los números directamente.","Más pasos es más camino; menos pasos es menos camino."],"ojo":"Esto solo vale si los pasos son iguales. Con pasos distintos, los números no se pueden comparar."}}'::jsonb, 11);
insert into learning_evidences (id, dba_id, num, texto) select '53eb4d65-fefe-5011-8452-c21d6e138db2'::uuid, d.id, 1, 'Mide longitudes con diferentes instrumentos y expresa el resultado en unidades estandarizadas o no estandarizadas comunes.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 5;
insert into learning_evidences (id, dba_id, num, texto) select '306d4e5d-075b-5e17-84cf-e81bbd475946'::uuid, d.id, 2, 'Compara objetos a partir de su longitud, masa, capacidad y duración de eventos.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 5;
insert into learning_evidences (id, dba_id, num, texto) select '3d179b36-5755-5902-8988-d34c7d97fdd4'::uuid, d.id, 3, 'Toma decisiones a partir de las mediciones realizadas y de acuerdo con los requerimientos del problema.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 5;
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('53eb4d65-fefe-5011-8452-c21d6e138db2'::uuid, 'multiple_choice', 'La mesa mide 4 cuartas. ¿Con qué la mediste?', '{"options":["Con la mano","Con un reloj","Con una balanza","Con un vaso"],"correctIndex":0,"ayuda":{"pista":"La medida te dice el instrumento: si dice cuartas, mediste con la mano.","pasos":["Para medir no siempre hace falta una regla: sirve la mano, el pie o cualquier objeto repetido.","Una cuarta es la mano abierta, del pulgar al meñique.","El nombre de la medida delata con qué se midió: pasos con los pies, clips con clips."],"ojo":"La unidad tiene que servir para lo que se mide: con un reloj no se mide una mesa."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('53eb4d65-fefe-5011-8452-c21d6e138db2'::uuid, 'multiple_choice', 'El salón mide 12 pasos. ¿Con qué lo mediste?', '{"options":["Con los pies","Con un reloj","Con una balanza","Con un vaso"],"correctIndex":0,"ayuda":{"pista":"La medida te dice el instrumento: si dice cuartas, mediste con la mano.","pasos":["Para medir no siempre hace falta una regla: sirve la mano, el pie o cualquier objeto repetido.","Una cuarta es la mano abierta, del pulgar al meñique.","El nombre de la medida delata con qué se midió: pasos con los pies, clips con clips."],"ojo":"La unidad tiene que servir para lo que se mide: con un reloj no se mide una mesa."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('53eb4d65-fefe-5011-8452-c21d6e138db2'::uuid, 'multiple_choice', '¿Cuál de estas cosas mediste con la mano?', '{"options":["La mesa: 4 cuartas","El salón: 12 pasos","El juego: 5 minutos","La bolsa: 2 kilos"],"correctIndex":0,"ayuda":{"pista":"La medida te dice el instrumento: si dice cuartas, mediste con la mano.","pasos":["Para medir no siempre hace falta una regla: sirve la mano, el pie o cualquier objeto repetido.","Una cuarta es la mano abierta, del pulgar al meñique.","El nombre de la medida delata con qué se midió: pasos con los pies, clips con clips."],"ojo":"La unidad tiene que servir para lo que se mide: con un reloj no se mide una mesa."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('306d4e5d-075b-5e17-84cf-e81bbd475946'::uuid, 'multiple_choice', '¿Cuál dura MÁS?', '{"options":["Una clase","Un parpadeo","Un estornudo","Un aplauso"],"correctIndex":0,"ayuda":{"pista":"Piensa cuánto tarda cada cosa de verdad, y ordénalas de la más corta a la más larga.","pasos":["Ordena las opciones por su duración: un parpadeo, un aplauso, un recreo, una clase, un día.","Algunas son de un segundo y otras de horas: la diferencia es enorme.","Elige la punta que te piden, la que dura más o la que dura menos."],"ojo":"Lee si piden MÁS o MENOS. Aquí no siempre piden lo mismo."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('306d4e5d-075b-5e17-84cf-e81bbd475946'::uuid, 'multiple_choice', '¿Cuál dura MÁS?', '{"options":["Un día","Una hora","Un minuto","Un segundo"],"correctIndex":0,"ayuda":{"pista":"Piensa cuánto tarda cada cosa de verdad, y ordénalas de la más corta a la más larga.","pasos":["Ordena las opciones por su duración: un parpadeo, un aplauso, un recreo, una clase, un día.","Algunas son de un segundo y otras de horas: la diferencia es enorme.","Elige la punta que te piden, la que dura más o la que dura menos."],"ojo":"Lee si piden MÁS o MENOS. Aquí no siempre piden lo mismo."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('306d4e5d-075b-5e17-84cf-e81bbd475946'::uuid, 'multiple_choice', '¿Cuál dura MENOS?', '{"options":["Un salto","Un recreo","Una clase","Una semana"],"correctIndex":0,"ayuda":{"pista":"Piensa cuánto tarda cada cosa de verdad, y ordénalas de la más corta a la más larga.","pasos":["Ordena las opciones por su duración: un parpadeo, un aplauso, un recreo, una clase, un día.","Algunas son de un segundo y otras de horas: la diferencia es enorme.","Elige la punta que te piden, la que dura más o la que dura menos."],"ojo":"Lee si piden MÁS o MENOS. Aquí no siempre piden lo mismo."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('306d4e5d-075b-5e17-84cf-e81bbd475946'::uuid, 'multiple_choice', '¿Cuál pesa MENOS?', '{"options":["Una pluma","Un libro","Un zapato","Una piedra"],"correctIndex":0,"ayuda":{"pista":"Imagina que cargas cada cosa. Ordénalas de la más liviana a la más pesada.","pasos":["Piensa en cada objeto con la mano: una pluma casi no se siente, una nevera no la levantas.","Ponlos en fila de mentiras, del más liviano al más pesado.","Elige la punta que te pide la pregunta."],"ojo":"Fíjate si piden el que MÁS pesa o el que MENOS pesa."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('306d4e5d-075b-5e17-84cf-e81bbd475946'::uuid, 'multiple_choice', '¿Cuál pesa MENOS?', '{"options":["Un algodón","Una manzana","Un ladrillo","Una silla"],"correctIndex":0,"ayuda":{"pista":"Imagina que cargas cada cosa. Ordénalas de la más liviana a la más pesada.","pasos":["Piensa en cada objeto con la mano: una pluma casi no se siente, una nevera no la levantas.","Ponlos en fila de mentiras, del más liviano al más pesado.","Elige la punta que te pide la pregunta."],"ojo":"Fíjate si piden el que MÁS pesa o el que MENOS pesa."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('306d4e5d-075b-5e17-84cf-e81bbd475946'::uuid, 'multiple_choice', '¿Cuál pesa MÁS?', '{"options":["Una nevera","Una silla","Un plato","Una cuchara"],"correctIndex":0,"ayuda":{"pista":"Imagina que cargas cada cosa. Ordénalas de la más liviana a la más pesada.","pasos":["Piensa en cada objeto con la mano: una pluma casi no se siente, una nevera no la levantas.","Ponlos en fila de mentiras, del más liviano al más pesado.","Elige la punta que te pide la pregunta."],"ojo":"Fíjate si piden el que MÁS pesa o el que MENOS pesa."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('306d4e5d-075b-5e17-84cf-e81bbd475946'::uuid, 'multiple_choice', 'Mira las dos cintas, medidas en clips. ¿Cómo son?', '{"options":["Igual de largas","La roja más larga","La azul más larga","No se pueden comparar"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Roja","valor":8},{"etiqueta":"Azul","valor":8}]},"ayuda":{"pista":"Mira las dos barras del dibujo: la más larga es la que mide más.","pasos":["Las dos cosas están medidas con la misma unidad, así que se pueden comparar.","Mira el dibujo: la barra más larga es la que mide más, y la más corta la que mide menos.","Si las dos barras llegan hasta el mismo punto, miden lo mismo."],"ojo":"Esto solo funciona porque las dos se midieron con lo MISMO."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('306d4e5d-075b-5e17-84cf-e81bbd475946'::uuid, 'multiple_choice', '¿Cuál cinta es más larga? (medidas en clips)', '{"options":["La roja","La azul","Son iguales","No se sabe"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Roja","valor":9},{"etiqueta":"Azul","valor":6}]},"ayuda":{"pista":"Mira las dos barras del dibujo: la más larga es la que mide más.","pasos":["Las dos cosas están medidas con la misma unidad, así que se pueden comparar.","Mira el dibujo: la barra más larga es la que mide más, y la más corta la que mide menos.","Si las dos barras llegan hasta el mismo punto, miden lo mismo."],"ojo":"Esto solo funciona porque las dos se midieron con lo MISMO."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('306d4e5d-075b-5e17-84cf-e81bbd475946'::uuid, 'multiple_choice', '¿Cuál cuerda es más corta? (medidas en cuartas)', '{"options":["La verde","La café","Son iguales","No se sabe"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Verde","valor":4},{"etiqueta":"Café","valor":7}]},"ayuda":{"pista":"Mira las dos barras del dibujo: la más larga es la que mide más.","pasos":["Las dos cosas están medidas con la misma unidad, así que se pueden comparar.","Mira el dibujo: la barra más larga es la que mide más, y la más corta la que mide menos.","Si las dos barras llegan hasta el mismo punto, miden lo mismo."],"ojo":"Esto solo funciona porque las dos se midieron con lo MISMO."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('306d4e5d-075b-5e17-84cf-e81bbd475946'::uuid, 'multiple_choice', 'Cada jarra llenó estos vasos. ¿Cuál tiene MÁS agua?', '{"options":["La jarra B","La jarra A","Las dos igual","No se sabe"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Jarra A","valor":4},{"etiqueta":"Jarra B","valor":7}]},"ayuda":{"pista":"El que llenó más vasos es el que tiene más adentro.","pasos":["Para comparar cuánto le cabe a dos recipientes, se llenan los dos con lo mismo.","Se cuenta cuántos vasos o pocillos salieron de cada uno.","El que dio más vasos es el que tenía más, aunque por fuera parezca más pequeño."],"ojo":"No se compara por el tamaño de afuera: se compara por lo que le cupo."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('306d4e5d-075b-5e17-84cf-e81bbd475946'::uuid, 'multiple_choice', 'Cada balde llenó estos vasos. ¿Cuál tiene MENOS agua?', '{"options":["El balde A","El balde B","Los dos igual","No se sabe"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Balde A","valor":3},{"etiqueta":"Balde B","valor":9}]},"ayuda":{"pista":"El que llenó más vasos es el que tiene más adentro.","pasos":["Para comparar cuánto le cabe a dos recipientes, se llenan los dos con lo mismo.","Se cuenta cuántos vasos o pocillos salieron de cada uno.","El que dio más vasos es el que tenía más, aunque por fuera parezca más pequeño."],"ojo":"No se compara por el tamaño de afuera: se compara por lo que le cupo."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('306d4e5d-075b-5e17-84cf-e81bbd475946'::uuid, 'multiple_choice', 'Cada olla lleva estos pocillos. ¿Cuál es más grande?', '{"options":["La olla B","La olla A","Las dos igual","No se sabe"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Olla A","valor":6},{"etiqueta":"Olla B","valor":10}]},"ayuda":{"pista":"El que llenó más vasos es el que tiene más adentro.","pasos":["Para comparar cuánto le cabe a dos recipientes, se llenan los dos con lo mismo.","Se cuenta cuántos vasos o pocillos salieron de cada uno.","El que dio más vasos es el que tenía más, aunque por fuera parezca más pequeño."],"ojo":"No se compara por el tamaño de afuera: se compara por lo que le cupo."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('53eb4d65-fefe-5011-8452-c21d6e138db2'::uuid, 'multiple_choice', '¿Cuántos clips más largo es el lápiz azul que el rojo?', '{"options":["2","8","1","4"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Rojo","valor":3},{"etiqueta":"Azul","valor":5}]},"ayuda":{"pista":"Para saber cuánto MÁS mide uno que otro, se resta la medida pequeña de la grande.","pasos":["Mira las dos barras y fíjate cuál es la más larga.","La pregunta es cuánto le sobra a esa por encima de la otra.","Eso se averigua restando: la medida grande menos la pequeña."],"ojo":"Aquí no se suman las dos medidas. Se busca la diferencia entre ellas."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('53eb4d65-fefe-5011-8452-c21d6e138db2'::uuid, 'multiple_choice', '¿Cuántos clips más larga es la cinta verde que la café?', '{"options":["5","13","4","7"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Café","valor":4},{"etiqueta":"Verde","valor":9}]},"ayuda":{"pista":"Para saber cuánto MÁS mide uno que otro, se resta la medida pequeña de la grande.","pasos":["Mira las dos barras y fíjate cuál es la más larga.","La pregunta es cuánto le sobra a esa por encima de la otra.","Eso se averigua restando: la medida grande menos la pequeña."],"ojo":"Aquí no se suman las dos medidas. Se busca la diferencia entre ellas."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('53eb4d65-fefe-5011-8452-c21d6e138db2'::uuid, 'multiple_choice', '¿Cuántas cuartas más larga es la mesa grande que la chica?', '{"options":["3","13","2","5"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Chica","valor":5},{"etiqueta":"Grande","valor":8}]},"ayuda":{"pista":"Para saber cuánto MÁS mide uno que otro, se resta la medida pequeña de la grande.","pasos":["Mira las dos barras y fíjate cuál es la más larga.","La pregunta es cuánto le sobra a esa por encima de la otra.","Eso se averigua restando: la medida grande menos la pequeña."],"ojo":"Aquí no se suman las dos medidas. Se busca la diferencia entre ellas."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('3d179b36-5755-5902-8988-d34c7d97fdd4'::uuid, 'multiple_choice', 'Necesitas 10 clips de cinta y tienes 6.', '{"options":["4","6","7","10"],"correctIndex":0,"operation":"6 + ? = 10"}'::jsonb, 7);
