insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('3d179b36-5755-5902-8988-d34c7d97fdd4'::uuid, 'multiple_choice', 'Tienes una cinta de 12 clips y usas 5.', '{"options":["7","6","9","11"],"correctIndex":0,"operation":"12 − 5 = ?"}'::jsonb, 8);
