insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('70a9e729-040d-5b19-82d4-3671f086bd15'::uuid, 'multiple_choice', '¿Cuántos lados tiene un triángulo?', '{"options":["3","4","5","1"],"correctIndex":0,"visual":{"tipo":"figura","nombre":"triángulo"},"ayuda":{"pista":"Cuenta los lados de la figura tocándolos con el dedo, uno por uno, dando la vuelta.","pasos":["Un lado es cada rayita recta que forma la figura.","Cuéntalos dando la vuelta completa y sin repetir ninguno.","El triángulo tiene 3 y el rectángulo tiene 4."],"ojo":"En estas figuras hay tantas puntas como lados: si cuentas 3 lados, hay 3 puntas."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('70a9e729-040d-5b19-82d4-3671f086bd15'::uuid, 'multiple_choice', '¿Cuántas puntas tiene un triángulo?', '{"options":["3","4","2","6"],"correctIndex":0,"visual":{"tipo":"figura","nombre":"triángulo"},"ayuda":{"pista":"Cuenta los lados de la figura tocándolos con el dedo, uno por uno, dando la vuelta.","pasos":["Un lado es cada rayita recta que forma la figura.","Cuéntalos dando la vuelta completa y sin repetir ninguno.","El triángulo tiene 3 y el rectángulo tiene 4."],"ojo":"En estas figuras hay tantas puntas como lados: si cuentas 3 lados, hay 3 puntas."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('70a9e729-040d-5b19-82d4-3671f086bd15'::uuid, 'multiple_choice', '¿Cuántos lados tiene un rectángulo?', '{"options":["4","3","5","6"],"correctIndex":0,"visual":{"tipo":"figura","nombre":"rectángulo"},"ayuda":{"pista":"Cuenta los lados de la figura tocándolos con el dedo, uno por uno, dando la vuelta.","pasos":["Un lado es cada rayita recta que forma la figura.","Cuéntalos dando la vuelta completa y sin repetir ninguno.","El triángulo tiene 3 y el rectángulo tiene 4."],"ojo":"En estas figuras hay tantas puntas como lados: si cuentas 3 lados, hay 3 puntas."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('8ba7fb31-6d3d-5177-8b7b-2d0ef0795c7c'::uuid, 'multiple_choice', '¿Con cuántos palitos haces un triángulo?', '{"options":["3","2","4","6"],"correctIndex":0,"visual":{"tipo":"figura","nombre":"triángulo"},"ayuda":{"pista":"Cada palito es un lado. Cuenta cuántos lados necesita la figura.","pasos":["Para armar una figura con palitos, necesitas un palito por cada lado.","El triángulo tiene 3 lados: 3 palitos. El cuadrado tiene 4: 4 palitos.","Y si juntas dos cuadrados iguales uno al lado del otro, queda una figura más larga que alta: un rectángulo."],"ojo":"Con menos palitos que lados la figura no cierra, y una figura abierta no es una figura."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('8ba7fb31-6d3d-5177-8b7b-2d0ef0795c7c'::uuid, 'multiple_choice', '¿Con cuántos palitos haces un cuadrado?', '{"options":["4","3","5","8"],"correctIndex":0,"visual":{"tipo":"figura","nombre":"cuadrado"},"ayuda":{"pista":"Cada palito es un lado. Cuenta cuántos lados necesita la figura.","pasos":["Para armar una figura con palitos, necesitas un palito por cada lado.","El triángulo tiene 3 lados: 3 palitos. El cuadrado tiene 4: 4 palitos.","Y si juntas dos cuadrados iguales uno al lado del otro, queda una figura más larga que alta: un rectángulo."],"ojo":"Con menos palitos que lados la figura no cierra, y una figura abierta no es una figura."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('8ba7fb31-6d3d-5177-8b7b-2d0ef0795c7c'::uuid, 'multiple_choice', 'Con 2 cuadrados iguales, uno al lado del otro, armas un:', '{"options":["Rectángulo","Círculo","Triángulo","Cubo"],"correctIndex":0,"figuras":["rectángulo","círculo","triángulo","cubo"],"ayuda":{"pista":"Cada palito es un lado. Cuenta cuántos lados necesita la figura.","pasos":["Para armar una figura con palitos, necesitas un palito por cada lado.","El triángulo tiene 3 lados: 3 palitos. El cuadrado tiene 4: 4 palitos.","Y si juntas dos cuadrados iguales uno al lado del otro, queda una figura más larga que alta: un rectángulo."],"ojo":"Con menos palitos que lados la figura no cierra, y una figura abierta no es una figura."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('70a9e729-040d-5b19-82d4-3671f086bd15'::uuid, 'multiple_choice', '¿Cuántos lados tiene un cuadrado?', '{"options":["4","3","5","6"],"correctIndex":0,"visual":{"tipo":"figura","nombre":"cuadrado"},"ayuda":{"pista":"Cuenta tocando con el dedo. Y fíjate si la figura tiene rayitas rectas o no tiene ninguna.","pasos":["El cuadrado tiene 4 lados iguales y 4 esquinas, una en cada punta.","En estas figuras siempre hay tantas esquinas como lados.","El círculo es distinto: es una sola línea curva, sin lados rectos y sin esquinas."],"ojo":"El círculo no tiene 1 lado: no tiene ninguno, porque un lado es una rayita recta."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('70a9e729-040d-5b19-82d4-3671f086bd15'::uuid, 'multiple_choice', '¿Cuántas esquinas tiene un cuadrado?', '{"options":["4","3","5","2"],"correctIndex":0,"visual":{"tipo":"figura","nombre":"cuadrado"},"ayuda":{"pista":"Cuenta tocando con el dedo. Y fíjate si la figura tiene rayitas rectas o no tiene ninguna.","pasos":["El cuadrado tiene 4 lados iguales y 4 esquinas, una en cada punta.","En estas figuras siempre hay tantas esquinas como lados.","El círculo es distinto: es una sola línea curva, sin lados rectos y sin esquinas."],"ojo":"El círculo no tiene 1 lado: no tiene ninguno, porque un lado es una rayita recta."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('70a9e729-040d-5b19-82d4-3671f086bd15'::uuid, 'multiple_choice', '¿Cuántos lados RECTOS tiene un círculo?', '{"options":["Ninguno","Uno","Dos","Cuatro"],"correctIndex":0,"visual":{"tipo":"figura","nombre":"círculo"},"ayuda":{"pista":"Cuenta tocando con el dedo. Y fíjate si la figura tiene rayitas rectas o no tiene ninguna.","pasos":["El cuadrado tiene 4 lados iguales y 4 esquinas, una en cada punta.","En estas figuras siempre hay tantas esquinas como lados.","El círculo es distinto: es una sola línea curva, sin lados rectos y sin esquinas."],"ojo":"El círculo no tiene 1 lado: no tiene ninguno, porque un lado es una rayita recta."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('8ba7fb31-6d3d-5177-8b7b-2d0ef0795c7c'::uuid, 'multiple_choice', 'Para armar un cohete, ¿qué forma va abajo del cono?', '{"options":["Cilindro","Esfera","Cubo","Pirámide"],"correctIndex":0,"figuras":["cilindro","esfera","cubo","pirámide"],"ayuda":{"pista":"Piensa en la forma del objeto de verdad y con qué cuerpo se parece cada pedazo.","pasos":["Los objetos del mundo están hechos de cuerpos geométricos pegados.","La punta que termina en pico es un cono; el tubo largo con dos tapas redondas es un cilindro.","Lo redondo por todas partes es una esfera, y lo de caras planas y esquinas, un cubo o una pirámide."],"ojo":"Mira qué forma tiene el PEDAZO que falta, no la del objeto entero."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('8ba7fb31-6d3d-5177-8b7b-2d0ef0795c7c'::uuid, 'multiple_choice', 'Un helado de cono, ¿qué forma lleva encima?', '{"options":["Esfera","Cubo","Pirámide","Cilindro"],"correctIndex":0,"figuras":["esfera","cubo","pirámide","cilindro"],"ayuda":{"pista":"Piensa en la forma del objeto de verdad y con qué cuerpo se parece cada pedazo.","pasos":["Los objetos del mundo están hechos de cuerpos geométricos pegados.","La punta que termina en pico es un cono; el tubo largo con dos tapas redondas es un cilindro.","Lo redondo por todas partes es una esfera, y lo de caras planas y esquinas, un cubo o una pirámide."],"ojo":"Mira qué forma tiene el PEDAZO que falta, no la del objeto entero."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('8ba7fb31-6d3d-5177-8b7b-2d0ef0795c7c'::uuid, 'multiple_choice', 'Una casa de juguete de cubo, ¿qué forma lleva de techo?', '{"options":["Pirámide","Esfera","Cilindro","Cono"],"correctIndex":0,"figuras":["pirámide","esfera","cilindro","cono"],"ayuda":{"pista":"Piensa en la forma del objeto de verdad y con qué cuerpo se parece cada pedazo.","pasos":["Los objetos del mundo están hechos de cuerpos geométricos pegados.","La punta que termina en pico es un cono; el tubo largo con dos tapas redondas es un cilindro.","Lo redondo por todas partes es una esfera, y lo de caras planas y esquinas, un cubo o una pirámide."],"ojo":"Mira qué forma tiene el PEDAZO que falta, no la del objeto entero."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e1001f1c-73ef-5049-8a75-af84700f0a06'::uuid, 'multiple_choice', 'Tiene 3 lados y 3 puntas. Es un:', '{"options":["Triángulo","Cuadrado","Círculo","Rectángulo"],"correctIndex":0,"figuras":["triángulo","cuadrado","círculo","rectángulo"],"ayuda":{"pista":"Cuenta los lados que menciona la descripción y busca la figura que los tenga.","pasos":["La descripción te da las pistas: cuántos lados, cuántas puntas, si son rectos o curvos.","3 lados y 3 puntas solo lo cumple el triángulo.","4 lados con dos más largos es el rectángulo; sin lados rectos ni puntas, el círculo."],"ojo":"El cuadrado y el rectángulo tienen los dos 4 lados. Los diferencia si son todos iguales o no."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e1001f1c-73ef-5049-8a75-af84700f0a06'::uuid, 'multiple_choice', 'Tiene 4 lados y 2 son más largos. Es un:', '{"options":["Rectángulo","Triángulo","Círculo","Cuadrado"],"correctIndex":0,"figuras":["rectángulo","triángulo","círculo","cuadrado"],"ayuda":{"pista":"Cuenta los lados que menciona la descripción y busca la figura que los tenga.","pasos":["La descripción te da las pistas: cuántos lados, cuántas puntas, si son rectos o curvos.","3 lados y 3 puntas solo lo cumple el triángulo.","4 lados con dos más largos es el rectángulo; sin lados rectos ni puntas, el círculo."],"ojo":"El cuadrado y el rectángulo tienen los dos 4 lados. Los diferencia si son todos iguales o no."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e1001f1c-73ef-5049-8a75-af84700f0a06'::uuid, 'multiple_choice', 'No tiene lados rectos ni puntas. Es un:', '{"options":["Círculo","Triángulo","Cuadrado","Rectángulo"],"correctIndex":0,"figuras":["círculo","triángulo","cuadrado","rectángulo"],"ayuda":{"pista":"Cuenta los lados que menciona la descripción y busca la figura que los tenga.","pasos":["La descripción te da las pistas: cuántos lados, cuántas puntas, si son rectos o curvos.","3 lados y 3 puntas solo lo cumple el triángulo.","4 lados con dos más largos es el rectángulo; sin lados rectos ni puntas, el círculo."],"ojo":"El cuadrado y el rectángulo tienen los dos 4 lados. Los diferencia si son todos iguales o no."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e1001f1c-73ef-5049-8a75-af84700f0a06'::uuid, 'multiple_choice', 'Tiene 4 lados iguales y 4 puntas. Es un:', '{"options":["Cuadrado","Rectángulo","Triángulo","Círculo"],"correctIndex":0,"figuras":["cuadrado","rectángulo","triángulo","círculo"],"ayuda":{"pista":"La descripción dice cuántos lados y cómo son. Eso alcanza para saber cuál es.","pasos":["4 lados IGUALES es el cuadrado; si dos son más largos, es el rectángulo.","3 lados iguales es el triángulo.","Y lo que rueda y no tiene puntas es el círculo, porque es todo curvo."],"ojo":"La palabra «iguales» es la que decide entre cuadrado y rectángulo."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e1001f1c-73ef-5049-8a75-af84700f0a06'::uuid, 'multiple_choice', 'Rueda y no tiene puntas. Es un:', '{"options":["Círculo","Cuadrado","Triángulo","Rectángulo"],"correctIndex":0,"figuras":["círculo","cuadrado","triángulo","rectángulo"],"ayuda":{"pista":"La descripción dice cuántos lados y cómo son. Eso alcanza para saber cuál es.","pasos":["4 lados IGUALES es el cuadrado; si dos son más largos, es el rectángulo.","3 lados iguales es el triángulo.","Y lo que rueda y no tiene puntas es el círculo, porque es todo curvo."],"ojo":"La palabra «iguales» es la que decide entre cuadrado y rectángulo."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e1001f1c-73ef-5049-8a75-af84700f0a06'::uuid, 'multiple_choice', 'Tiene 3 lados iguales. Es un:', '{"options":["Triángulo","Cuadrado","Círculo","Rectángulo"],"correctIndex":0,"figuras":["triángulo","cuadrado","círculo","rectángulo"],"ayuda":{"pista":"La descripción dice cuántos lados y cómo son. Eso alcanza para saber cuál es.","pasos":["4 lados IGUALES es el cuadrado; si dos son más largos, es el rectángulo.","3 lados iguales es el triángulo.","Y lo que rueda y no tiene puntas es el círculo, porque es todo curvo."],"ojo":"La palabra «iguales» es la que decide entre cuadrado y rectángulo."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('70a9e729-040d-5b19-82d4-3671f086bd15'::uuid, 'multiple_choice', '¿Cuál de estas cosas tiene el borde CURVO?', '{"options":["Un plato","Una regla","Un cuaderno","Un libro"],"correctIndex":0,"ayuda":{"pista":"Pasa el dedo por el borde de mentiras: si da la vuelta sin frenar, es curvo.","pasos":["Un borde curvo se sigue con el dedo sin tropezar con ninguna esquina.","Un borde recto va derecho y se frena en una esquina.","Los platos, las monedas y los anillos son curvos; las reglas, los libros y las mesas son rectos."],"ojo":"Mírale el borde, no el tamaño ni para qué sirve el objeto."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('70a9e729-040d-5b19-82d4-3671f086bd15'::uuid, 'multiple_choice', '¿Cuál de estas cosas tiene el borde RECTO?', '{"options":["Una regla","Un plato","Una moneda","Un anillo"],"correctIndex":0,"ayuda":{"pista":"Pasa el dedo por el borde de mentiras: si da la vuelta sin frenar, es curvo.","pasos":["Un borde curvo se sigue con el dedo sin tropezar con ninguna esquina.","Un borde recto va derecho y se frena en una esquina.","Los platos, las monedas y los anillos son curvos; las reglas, los libros y las mesas son rectos."],"ojo":"Mírale el borde, no el tamaño ni para qué sirve el objeto."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('70a9e729-040d-5b19-82d4-3671f086bd15'::uuid, 'multiple_choice', '¿Cuál de estas cosas es redonda?', '{"options":["Una moneda","Un libro","Una caja","Una puerta"],"correctIndex":0,"ayuda":{"pista":"Pasa el dedo por el borde de mentiras: si da la vuelta sin frenar, es curvo.","pasos":["Un borde curvo se sigue con el dedo sin tropezar con ninguna esquina.","Un borde recto va derecho y se frena en una esquina.","Los platos, las monedas y los anillos son curvos; las reglas, los libros y las mesas son rectos."],"ojo":"Mírale el borde, no el tamaño ni para qué sirve el objeto."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('6163b69e-6478-588a-89e0-999e126b8b1a'::uuid, 'multiple_choice', 'Una pelota tiene forma de:', '{"options":["Esfera","Cubo","Cilindro","Pirámide"],"correctIndex":0,"figuras":["esfera","cubo","cilindro","pirámide"],"ayuda":{"pista":"Piensa si el objeto rueda para todos lados o si tiene caras planas.","pasos":["La esfera es redonda por todas partes y rueda para cualquier lado: una pelota, una naranja.","El cubo tiene caras planas y no rueda.","Cuidado: la cara de un reloj se VE como un círculo plano, y una pelota es una esfera."],"ojo":"El círculo es plano, como un dibujo. La esfera es un cuerpo que se puede agarrar."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('6163b69e-6478-588a-89e0-999e126b8b1a'::uuid, 'multiple_choice', 'Una naranja tiene forma de:', '{"options":["Esfera","Cubo","Cono","Cilindro"],"correctIndex":0,"figuras":["esfera","cubo","cono","cilindro"],"ayuda":{"pista":"Piensa si el objeto rueda para todos lados o si tiene caras planas.","pasos":["La esfera es redonda por todas partes y rueda para cualquier lado: una pelota, una naranja.","El cubo tiene caras planas y no rueda.","Cuidado: la cara de un reloj se VE como un círculo plano, y una pelota es una esfera."],"ojo":"El círculo es plano, como un dibujo. La esfera es un cuerpo que se puede agarrar."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('6163b69e-6478-588a-89e0-999e126b8b1a'::uuid, 'multiple_choice', 'La cara de un reloj tiene forma de:', '{"options":["Círculo","Cuadrado","Triángulo","Rectángulo"],"correctIndex":0,"figuras":["círculo","cuadrado","triángulo","rectángulo"],"ayuda":{"pista":"Piensa si el objeto rueda para todos lados o si tiene caras planas.","pasos":["La esfera es redonda por todas partes y rueda para cualquier lado: una pelota, una naranja.","El cubo tiene caras planas y no rueda.","Cuidado: la cara de un reloj se VE como un círculo plano, y una pelota es una esfera."],"ojo":"El círculo es plano, como un dibujo. La esfera es un cuerpo que se puede agarrar."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('6163b69e-6478-588a-89e0-999e126b8b1a'::uuid, 'multiple_choice', 'Un dado tiene forma de:', '{"options":["Cubo","Esfera","Cono","Cilindro"],"correctIndex":0,"figuras":["cubo","esfera","cono","cilindro"],"ayuda":{"pista":"Cuéntale las caras de mentiras: ¿son todas cuadradas, o unas más largas?","pasos":["El cubo tiene 6 caras cuadradas, todas iguales: por eso un dado es un cubo.","El prisma también tiene 6 caras, pero unas más largas que otras: una caja de zapatos.","El cono tiene una punta arriba y una base redonda: un gorro de cumpleaños."],"ojo":"El cubo y el prisma se parecen. Lo que los distingue es si todas las caras son iguales."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('6163b69e-6478-588a-89e0-999e126b8b1a'::uuid, 'multiple_choice', 'Una caja de zapatos tiene forma de:', '{"options":["Prisma","Esfera","Cono","Cilindro"],"correctIndex":0,"figuras":["prisma","esfera","cono","cilindro"],"ayuda":{"pista":"Cuéntale las caras de mentiras: ¿son todas cuadradas, o unas más largas?","pasos":["El cubo tiene 6 caras cuadradas, todas iguales: por eso un dado es un cubo.","El prisma también tiene 6 caras, pero unas más largas que otras: una caja de zapatos.","El cono tiene una punta arriba y una base redonda: un gorro de cumpleaños."],"ojo":"El cubo y el prisma se parecen. Lo que los distingue es si todas las caras son iguales."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('6163b69e-6478-588a-89e0-999e126b8b1a'::uuid, 'multiple_choice', 'Un gorro de cumpleaños tiene forma de:', '{"options":["Cono","Cubo","Esfera","Cilindro"],"correctIndex":0,"figuras":["cono","cubo","esfera","cilindro"],"ayuda":{"pista":"Cuéntale las caras de mentiras: ¿son todas cuadradas, o unas más largas?","pasos":["El cubo tiene 6 caras cuadradas, todas iguales: por eso un dado es un cubo.","El prisma también tiene 6 caras, pero unas más largas que otras: una caja de zapatos.","El cono tiene una punta arriba y una base redonda: un gorro de cumpleaños."],"ojo":"El cubo y el prisma se parecen. Lo que los distingue es si todas las caras son iguales."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('6163b69e-6478-588a-89e0-999e126b8b1a'::uuid, 'multiple_choice', 'Una caja de galletas tiene forma de:', '{"options":["Prisma","Cilindro","Esfera","Cono"],"correctIndex":0,"figuras":["prisma","cilindro","esfera","cono"],"ayuda":{"pista":"Si tiene dos tapas redondas y rueda como un rodillo, es un cilindro.","pasos":["El cilindro tiene dos tapas redondas iguales y un tubo entre las dos: una lata, un rollo de papel.","Rueda, pero solo para un lado, no como una pelota.","La caja de galletas es distinta: tiene caras planas y esquinas, así que es un prisma."],"ojo":"Aquí no todos son cilindros. Míralo bien antes de contestar."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('6163b69e-6478-588a-89e0-999e126b8b1a'::uuid, 'multiple_choice', 'Una lata de gaseosa tiene forma de:', '{"options":["Cilindro","Cubo","Esfera","Cono"],"correctIndex":0,"figuras":["cilindro","cubo","esfera","cono"],"ayuda":{"pista":"Si tiene dos tapas redondas y rueda como un rodillo, es un cilindro.","pasos":["El cilindro tiene dos tapas redondas iguales y un tubo entre las dos: una lata, un rollo de papel.","Rueda, pero solo para un lado, no como una pelota.","La caja de galletas es distinta: tiene caras planas y esquinas, así que es un prisma."],"ojo":"Aquí no todos son cilindros. Míralo bien antes de contestar."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('6163b69e-6478-588a-89e0-999e126b8b1a'::uuid, 'multiple_choice', 'Un rollo de papel tiene forma de:', '{"options":["Cilindro","Cubo","Esfera","Pirámide"],"correctIndex":0,"figuras":["cilindro","cubo","esfera","pirámide"],"ayuda":{"pista":"Si tiene dos tapas redondas y rueda como un rodillo, es un cilindro.","pasos":["El cilindro tiene dos tapas redondas iguales y un tubo entre las dos: una lata, un rollo de papel.","Rueda, pero solo para un lado, no como una pelota.","La caja de galletas es distinta: tiene caras planas y esquinas, así que es un prisma."],"ojo":"Aquí no todos son cilindros. Míralo bien antes de contestar."}}'::jsonb, 10);
insert into learning_evidences (id, dba_id, num, texto) select '9bbe9b9b-7008-52db-84fc-48a1c6a92df8'::uuid, d.id, 1, 'Utiliza representaciones como planos para ubicarse en el espacio.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 7;
insert into learning_evidences (id, dba_id, num, texto) select '4e519d09-8455-557f-8e25-9bc6e384b1b6'::uuid, d.id, 2, 'Toma decisiones a partir de la ubicación espacial.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 7;
insert into learning_evidences (id, dba_id, num, texto) select '41dbdfd4-438b-5a20-89f9-665b28320a6d'::uuid, d.id, 3, 'Dibuja recorridos, para ello considera los ángulos y la lateralidad.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 7;
insert into learning_evidences (id, dba_id, num, texto) select '54c59dd5-9f94-5281-8342-45638d096b97'::uuid, d.id, 4, 'Compara distancias a partir de la observación del plano al estimar con pasos, baldosas, etc.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 7;
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('9bbe9b9b-7008-52db-84fc-48a1c6a92df8'::uuid, 'multiple_choice', 'El perro está DEBAJO de la mesa. Entonces la mesa está:', '{"options":["Encima del perro","Debajo del perro","Al lado del perro","Lejos del perro"],"correctIndex":0,"ayuda":{"pista":"Ponte en el lugar del otro objeto: lo que está debajo de algo tiene ese algo encima.","pasos":["Estar encima y estar debajo son la misma situación vista desde los dos lados.","Si el perro está debajo de la mesa, desde el perro la mesa se ve arriba.","Lo mismo con dentro: si el gato está dentro de la caja, la caja lo rodea por todos lados."],"ojo":"Si los dos estuvieran debajo del otro, alguno tendría que estar en dos sitios a la vez."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('9bbe9b9b-7008-52db-84fc-48a1c6a92df8'::uuid, 'multiple_choice', 'El libro está ENCIMA del cuaderno. El cuaderno está:', '{"options":["Debajo del libro","Encima del libro","Al lado del libro","Lejos del libro"],"correctIndex":0,"ayuda":{"pista":"Ponte en el lugar del otro objeto: lo que está debajo de algo tiene ese algo encima.","pasos":["Estar encima y estar debajo son la misma situación vista desde los dos lados.","Si el perro está debajo de la mesa, desde el perro la mesa se ve arriba.","Lo mismo con dentro: si el gato está dentro de la caja, la caja lo rodea por todos lados."],"ojo":"Si los dos estuvieran debajo del otro, alguno tendría que estar en dos sitios a la vez."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('9bbe9b9b-7008-52db-84fc-48a1c6a92df8'::uuid, 'multiple_choice', 'El gato está DENTRO de la caja. La caja está:', '{"options":["Alrededor del gato","Dentro del gato","Debajo del gato","Lejos del gato"],"correctIndex":0,"ayuda":{"pista":"Ponte en el lugar del otro objeto: lo que está debajo de algo tiene ese algo encima.","pasos":["Estar encima y estar debajo son la misma situación vista desde los dos lados.","Si el perro está debajo de la mesa, desde el perro la mesa se ve arriba.","Lo mismo con dentro: si el gato está dentro de la caja, la caja lo rodea por todos lados."],"ojo":"Si los dos estuvieran debajo del otro, alguno tendría que estar en dos sitios a la vez."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('54c59dd5-9f94-5281-8342-45638d096b97'::uuid, 'multiple_choice', 'Dos caminos al parque, medidos en pasos. ¿Cuál es MÁS LARGO?', '{"options":["Por la tienda","Por el puente","Miden igual","No se puede saber"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Por la tienda","valor":30},{"etiqueta":"Por el puente","valor":12}]},"ayuda":{"pista":"Los dos caminos están medidos con lo mismo. Compara los dos números.","pasos":["Mira las dos barras del dibujo: cada una es un camino.","La barra más larga es el camino más largo, y la más corta el camino más corto.","Si las dos miden igual, da lo mismo por dónde te vayas."],"ojo":"Lee si piden el MÁS largo o el MÁS corto: es lo único que cambia."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('54c59dd5-9f94-5281-8342-45638d096b97'::uuid, 'multiple_choice', 'Dos caminos al colegio, medidos en pasos. ¿Cuál es MÁS CORTO?', '{"options":["Por el puente","Por la loma","Miden igual","No se puede saber"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Por el puente","valor":6},{"etiqueta":"Por la loma","valor":14}]},"ayuda":{"pista":"Los dos caminos están medidos con lo mismo. Compara los dos números.","pasos":["Mira las dos barras del dibujo: cada una es un camino.","La barra más larga es el camino más largo, y la más corta el camino más corto.","Si las dos miden igual, da lo mismo por dónde te vayas."],"ojo":"Lee si piden el MÁS largo o el MÁS corto: es lo único que cambia."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('54c59dd5-9f94-5281-8342-45638d096b97'::uuid, 'multiple_choice', 'En el plano, los dos caminos miden lo mismo. Entonces:', '{"options":["Da igual cuál tomes","El A es más corto","El B es más corto","No se pueden comparar"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Camino A","valor":9},{"etiqueta":"Camino B","valor":9}]},"ayuda":{"pista":"Los dos caminos están medidos con lo mismo. Compara los dos números.","pasos":["Mira las dos barras del dibujo: cada una es un camino.","La barra más larga es el camino más largo, y la más corta el camino más corto.","Si las dos miden igual, da lo mismo por dónde te vayas."],"ojo":"Lee si piden el MÁS largo o el MÁS corto: es lo único que cambia."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('54c59dd5-9f94-5281-8342-45638d096b97'::uuid, 'multiple_choice', 'Desde tu casa, en pasos. ¿Cuál queda MÁS CERCA?', '{"options":["La tienda","El parque","Quedan igual","No se sabe"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Tienda","valor":10},{"etiqueta":"Parque","valor":25}]},"ayuda":{"pista":"Más cerca es el número más pequeño de pasos; más lejos es el más grande.","pasos":["Los pasos o las cuadras dicen cuánto hay que caminar hasta cada lugar.","Menos pasos es más cerca. Más pasos es más lejos.","Como los dos se midieron desde tu casa y con lo mismo, se pueden comparar."],"ojo":"Cerca y lejos son al revés en los números: el más cerca es el número más pequeño."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('54c59dd5-9f94-5281-8342-45638d096b97'::uuid, 'multiple_choice', 'Desde tu casa, en pasos. ¿Cuál queda MÁS LEJOS?', '{"options":["El colegio","La panadería","Quedan igual","No se sabe"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Colegio","valor":40},{"etiqueta":"Panadería","valor":15}]},"ayuda":{"pista":"Más cerca es el número más pequeño de pasos; más lejos es el más grande.","pasos":["Los pasos o las cuadras dicen cuánto hay que caminar hasta cada lugar.","Menos pasos es más cerca. Más pasos es más lejos.","Como los dos se midieron desde tu casa y con lo mismo, se pueden comparar."],"ojo":"Cerca y lejos son al revés en los números: el más cerca es el número más pequeño."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('54c59dd5-9f94-5281-8342-45638d096b97'::uuid, 'multiple_choice', 'Desde tu casa, en cuadras. ¿Cuál queda MÁS CERCA?', '{"options":["La iglesia","El parque","Quedan igual","No se sabe"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Iglesia","valor":2},{"etiqueta":"Parque","valor":5}]},"ayuda":{"pista":"Más cerca es el número más pequeño de pasos; más lejos es el más grande.","pasos":["Los pasos o las cuadras dicen cuánto hay que caminar hasta cada lugar.","Menos pasos es más cerca. Más pasos es más lejos.","Como los dos se midieron desde tu casa y con lo mismo, se pueden comparar."],"ojo":"Cerca y lejos son al revés en los números: el más cerca es el número más pequeño."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('54c59dd5-9f94-5281-8342-45638d096b97'::uuid, 'multiple_choice', 'Un camino de 3 cuadras es ___ que uno de 6 cuadras.', '{"options":["Más corto","Más largo","Igual de largo","El doble de largo"],"correctIndex":0,"ayuda":{"pista":"Compara los dos números de cuadras y di cómo es el primero comparado con el segundo.","pasos":["La frase compara el primer camino CON el segundo, en ese orden.","Si el primer número es más pequeño, el primer camino es más corto.","Si los dos números son iguales, los caminos son igual de largos."],"ojo":"Lee en qué orden están. Cambiar el orden cambia la respuesta."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('54c59dd5-9f94-5281-8342-45638d096b97'::uuid, 'multiple_choice', 'Un camino de 9 cuadras es ___ que uno de 4 cuadras.', '{"options":["Más largo","Más corto","Igual de largo","La mitad de largo"],"correctIndex":0,"ayuda":{"pista":"Compara los dos números de cuadras y di cómo es el primero comparado con el segundo.","pasos":["La frase compara el primer camino CON el segundo, en ese orden.","Si el primer número es más pequeño, el primer camino es más corto.","Si los dos números son iguales, los caminos son igual de largos."],"ojo":"Lee en qué orden están. Cambiar el orden cambia la respuesta."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('54c59dd5-9f94-5281-8342-45638d096b97'::uuid, 'multiple_choice', 'Un camino de 5 cuadras y otro de 5 cuadras son:', '{"options":["Igual de largos","Uno el doble del otro","Uno la mitad del otro","No se pueden comparar"],"correctIndex":0,"ayuda":{"pista":"Compara los dos números de cuadras y di cómo es el primero comparado con el segundo.","pasos":["La frase compara el primer camino CON el segundo, en ese orden.","Si el primer número es más pequeño, el primer camino es más corto.","Si los dos números son iguales, los caminos son igual de largos."],"ojo":"Lee en qué orden están. Cambiar el orden cambia la respuesta."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('41dbdfd4-438b-5a20-89f9-665b28320a6d'::uuid, 'multiple_choice', 'Lápiz a la derecha, borrador a la izquierda. Coges el lápiz con:', '{"options":["La mano derecha","La mano izquierda","Las dos manos","Ninguna mano"],"correctIndex":0,"ayuda":{"pista":"Levanta de verdad la mano con la que escribes y ubícate desde ahí.","pasos":["Tu derecha y tu izquierda van contigo: dependen de para dónde estés mirando.","Lo que está a tu derecha se alcanza con la mano derecha.","Y siempre son dos: si una es la derecha, la otra es la izquierda."],"ojo":"La derecha de quien está al frente tuyo es tu izquierda. Por eso hay que ubicarse en uno mismo."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('41dbdfd4-438b-5a20-89f9-665b28320a6d'::uuid, 'multiple_choice', 'Lápiz a la derecha, borrador a la izquierda. Coges el borrador con:', '{"options":["La mano izquierda","La mano derecha","Las dos manos","Ninguna mano"],"correctIndex":0,"ayuda":{"pista":"Levanta de verdad la mano con la que escribes y ubícate desde ahí.","pasos":["Tu derecha y tu izquierda van contigo: dependen de para dónde estés mirando.","Lo que está a tu derecha se alcanza con la mano derecha.","Y siempre son dos: si una es la derecha, la otra es la izquierda."],"ojo":"La derecha de quien está al frente tuyo es tu izquierda. Por eso hay que ubicarse en uno mismo."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('41dbdfd4-438b-5a20-89f9-665b28320a6d'::uuid, 'multiple_choice', 'Si levantas la mano derecha, la otra mano es:', '{"options":["La izquierda","También la derecha","La de arriba","Ninguna"],"correctIndex":0,"ayuda":{"pista":"Levanta de verdad la mano con la que escribes y ubícate desde ahí.","pasos":["Tu derecha y tu izquierda van contigo: dependen de para dónde estés mirando.","Lo que está a tu derecha se alcanza con la mano derecha.","Y siempre son dos: si una es la derecha, la otra es la izquierda."],"ojo":"La derecha de quien está al frente tuyo es tu izquierda. Por eso hay que ubicarse en uno mismo."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('41dbdfd4-438b-5a20-89f9-665b28320a6d'::uuid, 'multiple_choice', 'Vas caminando y das media vuelta. Ahora vas:', '{"options":["De regreso","Para el mismo lado","Hacia arriba","Sin moverte"],"correctIndex":0,"ayuda":{"pista":"Haz el giro con el cuerpo, despacio, y fíjate para dónde quedas mirando.","pasos":["Media vuelta te deja mirando justo para el lado contrario: vuelves por donde viniste.","Un cuarto de giro a la derecha te deja mirando a la derecha.","Una vuelta completa te deja mirando para donde ya ibas: es como no haber girado."],"ojo":"Media vuelta y vuelta completa suenan parecido y dejan en lados opuestos."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('41dbdfd4-438b-5a20-89f9-665b28320a6d'::uuid, 'multiple_choice', 'Caminas y giras a la derecha. Giras otra vez a la derecha. Vas:', '{"options":["De regreso","Hacia la derecha","Hacia la izquierda","De frente"],"correctIndex":0,"ayuda":{"pista":"Haz el giro con el cuerpo, despacio, y fíjate para dónde quedas mirando.","pasos":["Media vuelta te deja mirando justo para el lado contrario: vuelves por donde viniste.","Un cuarto de giro a la derecha te deja mirando a la derecha.","Una vuelta completa te deja mirando para donde ya ibas: es como no haber girado."],"ojo":"Media vuelta y vuelta completa suenan parecido y dejan en lados opuestos."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('41dbdfd4-438b-5a20-89f9-665b28320a6d'::uuid, 'multiple_choice', 'Das una vuelta completa. Ahora vas:', '{"options":["Para el mismo lado","De regreso","Hacia la derecha","Hacia arriba"],"correctIndex":0,"ayuda":{"pista":"Haz el giro con el cuerpo, despacio, y fíjate para dónde quedas mirando.","pasos":["Media vuelta te deja mirando justo para el lado contrario: vuelves por donde viniste.","Un cuarto de giro a la derecha te deja mirando a la derecha.","Una vuelta completa te deja mirando para donde ya ibas: es como no haber girado."],"ojo":"Media vuelta y vuelta completa suenan parecido y dejan en lados opuestos."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('9bbe9b9b-7008-52db-84fc-48a1c6a92df8'::uuid, 'multiple_choice', 'En el plano, el colegio está debajo de tu casa. Para llegar:', '{"options":["Bajas","Subes","No te mueves","Das la vuelta"],"correctIndex":0,"ayuda":{"pista":"En un plano, lo que está arriba en el papel se alcanza subiendo.","pasos":["Un plano es el dibujo de un lugar visto desde arriba.","Lo que aparece arriba en el dibujo queda hacia allá; lo de abajo, hacia acá.","Para llegar, te mueves en la misma dirección en la que está dibujado."],"ojo":"Moverse al contrario de como está en el plano te aleja en vez de acercarte."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('9bbe9b9b-7008-52db-84fc-48a1c6a92df8'::uuid, 'multiple_choice', 'En el plano, la tienda está arriba de tu casa. Para llegar:', '{"options":["Subes","Bajas","No te mueves","Das la vuelta"],"correctIndex":0,"ayuda":{"pista":"En un plano, lo que está arriba en el papel se alcanza subiendo.","pasos":["Un plano es el dibujo de un lugar visto desde arriba.","Lo que aparece arriba en el dibujo queda hacia allá; lo de abajo, hacia acá.","Para llegar, te mueves en la misma dirección en la que está dibujado."],"ojo":"Moverse al contrario de como está en el plano te aleja en vez de acercarte."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('9bbe9b9b-7008-52db-84fc-48a1c6a92df8'::uuid, 'multiple_choice', 'En el plano, tu casa está arriba del parque. Para ir al parque:', '{"options":["Bajas","Subes","No te mueves","Das la vuelta"],"correctIndex":0,"ayuda":{"pista":"En un plano, lo que está arriba en el papel se alcanza subiendo.","pasos":["Un plano es el dibujo de un lugar visto desde arriba.","Lo que aparece arriba en el dibujo queda hacia allá; lo de abajo, hacia acá.","Para llegar, te mueves en la misma dirección en la que está dibujado."],"ojo":"Moverse al contrario de como está en el plano te aleja en vez de acercarte."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('9bbe9b9b-7008-52db-84fc-48a1c6a92df8'::uuid, 'multiple_choice', 'Estás en la puerta. El tablero está al frente. Para llegar:', '{"options":["Camino derecho","Doy la vuelta","Camino hacia atrás","Me quedo quieto"],"correctIndex":0,"ayuda":{"pista":"Piensa qué es lo PRIMERO que tendrías que hacer para arrancar hacia allá.","pasos":["Un recorrido se arma por pasos, y la pregunta es por el primero.","Mira dónde estás parado y hacia dónde queda lo que buscas.","El primer paso es moverte en esa dirección: al frente, cruzando, o hasta el fondo."],"ojo":"Quedarse quieto o irse para el otro lado no acerca a ninguna parte."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('9bbe9b9b-7008-52db-84fc-48a1c6a92df8'::uuid, 'multiple_choice', 'El baño queda al otro lado del colegio. Para llegar primero:', '{"options":["Salgo del salón","Me quedo sentado","Subo al techo","Abro la ventana"],"correctIndex":0,"ayuda":{"pista":"Piensa qué es lo PRIMERO que tendrías que hacer para arrancar hacia allá.","pasos":["Un recorrido se arma por pasos, y la pregunta es por el primero.","Mira dónde estás parado y hacia dónde queda lo que buscas.","El primer paso es moverte en esa dirección: al frente, cruzando, o hasta el fondo."],"ojo":"Quedarse quieto o irse para el otro lado no acerca a ninguna parte."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('9bbe9b9b-7008-52db-84fc-48a1c6a92df8'::uuid, 'multiple_choice', 'Tu puesto está en la última fila. Para llegar:', '{"options":["Camino hasta el fondo","Me quedo en la puerta","Voy al tablero","Salgo del salón"],"correctIndex":0,"ayuda":{"pista":"Piensa qué es lo PRIMERO que tendrías que hacer para arrancar hacia allá.","pasos":["Un recorrido se arma por pasos, y la pregunta es por el primero.","Mira dónde estás parado y hacia dónde queda lo que buscas.","El primer paso es moverte en esa dirección: al frente, cruzando, o hasta el fondo."],"ojo":"Quedarse quieto o irse para el otro lado no acerca a ninguna parte."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('4e519d09-8455-557f-8e25-9bc6e384b1b6'::uuid, 'multiple_choice', 'El parque queda más lejos que la tienda. Llegar allá toma:', '{"options":["Más tiempo","Menos tiempo","El mismo tiempo","Nada de tiempo"],"correctIndex":0,"ayuda":{"pista":"Más lejos es más camino, y más camino es más tiempo caminando.","pasos":["Si dos lugares están a distinta distancia, llegar a ellos toma distinto tiempo.","Al más lejano se demora más; al más cercano, menos.","Y si están a la misma distancia, llegar toma el mismo tiempo."],"ojo":"Esto vale si vas igual de rápido a los dos lados."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('4e519d09-8455-557f-8e25-9bc6e384b1b6'::uuid, 'multiple_choice', 'El colegio queda más cerca que la finca. Llegar toma:', '{"options":["Menos tiempo","Más tiempo","El mismo tiempo","Nada de tiempo"],"correctIndex":0,"ayuda":{"pista":"Más lejos es más camino, y más camino es más tiempo caminando.","pasos":["Si dos lugares están a distinta distancia, llegar a ellos toma distinto tiempo.","Al más lejano se demora más; al más cercano, menos.","Y si están a la misma distancia, llegar toma el mismo tiempo."],"ojo":"Esto vale si vas igual de rápido a los dos lados."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('4e519d09-8455-557f-8e25-9bc6e384b1b6'::uuid, 'multiple_choice', 'Dos casas quedan a la misma distancia. Llegar toma:', '{"options":["Lo mismo para las dos","Más tiempo para una","Menos tiempo para una","No se puede saber"],"correctIndex":0,"ayuda":{"pista":"Más lejos es más camino, y más camino es más tiempo caminando.","pasos":["Si dos lugares están a distinta distancia, llegar a ellos toma distinto tiempo.","Al más lejano se demora más; al más cercano, menos.","Y si están a la misma distancia, llegar toma el mismo tiempo."],"ojo":"Esto vale si vas igual de rápido a los dos lados."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('4e519d09-8455-557f-8e25-9bc6e384b1b6'::uuid, 'multiple_choice', '¿Cuál indicación sirve para llegar a un lugar?', '{"options":["Camina y gira en la esquina","Camina hasta que llegues","Queda por allá derechito","Es la casa más bonita"],"correctIndex":0,"ayuda":{"pista":"Una buena indicación dice CUÁNTO avanzar y PARA DÓNDE girar.","pasos":["Para llegar a un sitio hay que saber dos cosas: cuánto caminar y hacia dónde.","«Camina 2 cuadras y gira» tiene las dos: un número y una dirección.","«Queda por ahí» o «es una casa bonita» no sirven: no dicen ni cuánto ni para dónde."],"ojo":"Describir cómo es el lugar no ayuda a llegar si no dices el camino."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('4e519d09-8455-557f-8e25-9bc6e384b1b6'::uuid, 'multiple_choice', '¿Cuál indicación es más clara?', '{"options":["Sube al tercer piso y gira","Queda por ahí arribita","Está en un piso de arriba","Es la puerta más bonita"],"correctIndex":0,"ayuda":{"pista":"Una buena indicación dice CUÁNTO avanzar y PARA DÓNDE girar.","pasos":["Para llegar a un sitio hay que saber dos cosas: cuánto caminar y hacia dónde.","«Camina 2 cuadras y gira» tiene las dos: un número y una dirección.","«Queda por ahí» o «es una casa bonita» no sirven: no dicen ni cuánto ni para dónde."],"ojo":"Describir cómo es el lugar no ayuda a llegar si no dices el camino."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('4e519d09-8455-557f-8e25-9bc6e384b1b6'::uuid, 'multiple_choice', 'Para explicar un camino sirve decir:', '{"options":["Cuántas cuadras y para dónde","Que queda lejos","Que es bonito","Que es de color azul"],"correctIndex":0,"ayuda":{"pista":"Una buena indicación dice CUÁNTO avanzar y PARA DÓNDE girar.","pasos":["Para llegar a un sitio hay que saber dos cosas: cuánto caminar y hacia dónde.","«Camina 2 cuadras y gira» tiene las dos: un número y una dirección.","«Queda por ahí» o «es una casa bonita» no sirven: no dicen ni cuánto ni para dónde."],"ojo":"Describir cómo es el lugar no ayuda a llegar si no dices el camino."}}'::jsonb, 10);
insert into learning_evidences (id, dba_id, num, texto) select '06c20ed3-3dc6-50a4-87af-9ad1f681cbfb'::uuid, d.id, 1, 'Identifica y nombra diferencias entre objetos o grupos de objetos.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 8;
insert into learning_evidences (id, dba_id, num, texto) select '95a58dc6-7175-58d3-8f97-52cf91ff252d'::uuid, d.id, 2, 'Comunica las características identificadas y justifica las diferencias que encuentra.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 8;
insert into learning_evidences (id, dba_id, num, texto) select 'ecf8e0e0-26bd-5acf-8613-914ffe6a1e87'::uuid, d.id, 3, 'Establece relaciones de dependencia entre magnitudes.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 8;
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('06c20ed3-3dc6-50a4-87af-9ad1f681cbfb'::uuid, 'multiple_choice', 'Un vaso tenía 2 bolas. Ahora tiene 5. ¿Qué pasó?', '{"options":["Le pusieron más","Le quitaron","No cambió nada","Se hicieron grandes"],"correctIndex":0,"ayuda":{"pista":"Compara el número de antes con el de ahora: ¿subió o bajó?","pasos":["Mira cuánto había antes y cuánto hay ahora.","Si ahora hay más, es porque alguien agregó.","Si ahora hay menos, es porque alguien quitó, se comió o se llevó."],"ojo":"Las cosas no cambian de cantidad solas: si hay más o menos, alguien hizo algo."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('06c20ed3-3dc6-50a4-87af-9ad1f681cbfb'::uuid, 'multiple_choice', 'Había 8 galletas. Ahora hay 3. ¿Qué pasó?', '{"options":["Quitaron algunas","Pusieron más","No cambió nada","Se partieron a la mitad"],"correctIndex":0,"ayuda":{"pista":"Compara el número de antes con el de ahora: ¿subió o bajó?","pasos":["Mira cuánto había antes y cuánto hay ahora.","Si ahora hay más, es porque alguien agregó.","Si ahora hay menos, es porque alguien quitó, se comió o se llevó."],"ojo":"Las cosas no cambian de cantidad solas: si hay más o menos, alguien hizo algo."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('06c20ed3-3dc6-50a4-87af-9ad1f681cbfb'::uuid, 'multiple_choice', 'El frasco tenía 4 dulces. Ahora tiene 9. ¿Qué pasó?', '{"options":["Echaron más dulces","Sacaron dulces","No cambió nada","Se derritieron"],"correctIndex":0,"ayuda":{"pista":"Compara el número de antes con el de ahora: ¿subió o bajó?","pasos":["Mira cuánto había antes y cuánto hay ahora.","Si ahora hay más, es porque alguien agregó.","Si ahora hay menos, es porque alguien quitó, se comió o se llevó."],"ojo":"Las cosas no cambian de cantidad solas: si hay más o menos, alguien hizo algo."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('06c20ed3-3dc6-50a4-87af-9ad1f681cbfb'::uuid, 'multiple_choice', 'Tenías 10 dulces. Ahora tienes 6. Entonces:', '{"options":["Te faltan 4","Te sobran 4","Te faltan 6","No cambió nada"],"correctIndex":0,"ayuda":{"pista":"Además de mirar si subió o bajó, cuenta CUÁNTO cambió de uno a otro.","pasos":["Primero fíjate si la cantidad subió o bajó.","Después cuenta cuánto: desde el número pequeño hasta el grande.","Ese número es lo que ganaste, lo que te falta o lo que quitaron."],"ojo":"El cambio no es ninguno de los dos números: es la diferencia entre ellos."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('06c20ed3-3dc6-50a4-87af-9ad1f681cbfb'::uuid, 'multiple_choice', 'Tenías 7 fichas. Ahora tienes 9. Entonces:', '{"options":["Ganaste 2","Perdiste 2","Ganaste 9","No cambió nada"],"correctIndex":0,"ayuda":{"pista":"Además de mirar si subió o bajó, cuenta CUÁNTO cambió de uno a otro.","pasos":["Primero fíjate si la cantidad subió o bajó.","Después cuenta cuánto: desde el número pequeño hasta el grande.","Ese número es lo que ganaste, lo que te falta o lo que quitaron."],"ojo":"El cambio no es ninguno de los dos números: es la diferencia entre ellos."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('06c20ed3-3dc6-50a4-87af-9ad1f681cbfb'::uuid, 'multiple_choice', 'Había 12 sillas. Ahora hay 8. Entonces:', '{"options":["Quitaron 4","Pusieron 4","Quitaron 8","No cambió nada"],"correctIndex":0,"ayuda":{"pista":"Además de mirar si subió o bajó, cuenta CUÁNTO cambió de uno a otro.","pasos":["Primero fíjate si la cantidad subió o bajó.","Después cuenta cuánto: desde el número pequeño hasta el grande.","Ese número es lo que ganaste, lo que te falta o lo que quitaron."],"ojo":"El cambio no es ninguno de los dos números: es la diferencia entre ellos."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('06c20ed3-3dc6-50a4-87af-9ad1f681cbfb'::uuid, 'multiple_choice', 'Un grupo tiene 4 bolas y el otro tiene 4 bolas. Son:', '{"options":["Iguales en cantidad","El primero tiene más","El segundo tiene más","No se puede saber"],"correctIndex":0,"ayuda":{"pista":"Compara los dos números y fíjate en el ORDEN en que los nombra la frase.","pasos":["Si los dos números son iguales, los grupos tienen la misma cantidad.","Si son distintos, el del número más grande tiene más.","Fíjate cuál se nombró primero y cuál segundo, porque la respuesta los llama así."],"ojo":"Saber cuál tiene más no basta: hay que decir si es el primero o el segundo."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('06c20ed3-3dc6-50a4-87af-9ad1f681cbfb'::uuid, 'multiple_choice', 'Un grupo tiene 5 fichas y el otro 8. Entonces:', '{"options":["El segundo tiene más","El primero tiene más","Son iguales","No se sabe"],"correctIndex":0,"ayuda":{"pista":"Compara los dos números y fíjate en el ORDEN en que los nombra la frase.","pasos":["Si los dos números son iguales, los grupos tienen la misma cantidad.","Si son distintos, el del número más grande tiene más.","Fíjate cuál se nombró primero y cuál segundo, porque la respuesta los llama así."],"ojo":"Saber cuál tiene más no basta: hay que decir si es el primero o el segundo."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('06c20ed3-3dc6-50a4-87af-9ad1f681cbfb'::uuid, 'multiple_choice', 'Un grupo tiene 9 lápices y el otro 6. Entonces:', '{"options":["El primero tiene más","El segundo tiene más","Son iguales","No se sabe"],"correctIndex":0,"ayuda":{"pista":"Compara los dos números y fíjate en el ORDEN en que los nombra la frase.","pasos":["Si los dos números son iguales, los grupos tienen la misma cantidad.","Si son distintos, el del número más grande tiene más.","Fíjate cuál se nombró primero y cuál segundo, porque la respuesta los llama así."],"ojo":"Saber cuál tiene más no basta: hay que decir si es el primero o el segundo."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('95a58dc6-7175-58d3-8f97-52cf91ff252d'::uuid, 'multiple_choice', 'Un grupo tiene 3 patos en el agua. El otro, 3 patos con sombrero.', '{"options":["Se diferencian en el sombrero","Se diferencian en cuántos patos hay","No se diferencian en nada","Se diferencian en el agua"],"correctIndex":0,"ayuda":{"pista":"Los dos grupos tienen lo mismo en cantidad. Busca en qué se ven distintos.","pasos":["Dos cosas se pueden diferenciar en la cantidad o en cómo son.","Aquí la cantidad es la misma, así que la diferencia está en otra parte.","Mírales el tamaño, si tienen algo puesto, o si están llenos o vacíos."],"ojo":"Si hay la misma cantidad en los dos, la diferencia NO puede ser la cantidad."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('95a58dc6-7175-58d3-8f97-52cf91ff252d'::uuid, 'multiple_choice', 'Dos perros iguales, uno grande y uno chiquito.', '{"options":["Se diferencian en el tamaño","Se diferencian en la cantidad","No se diferencian","Se diferencian en el nombre"],"correctIndex":0,"ayuda":{"pista":"Los dos grupos tienen lo mismo en cantidad. Busca en qué se ven distintos.","pasos":["Dos cosas se pueden diferenciar en la cantidad o en cómo son.","Aquí la cantidad es la misma, así que la diferencia está en otra parte.","Mírales el tamaño, si tienen algo puesto, o si están llenos o vacíos."],"ojo":"Si hay la misma cantidad en los dos, la diferencia NO puede ser la cantidad."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('95a58dc6-7175-58d3-8f97-52cf91ff252d'::uuid, 'multiple_choice', 'Dos vasos iguales, uno lleno y otro vacío.', '{"options":["Se diferencian en el agua","Se diferencian en la forma","No se diferencian","Se diferencian en el color"],"correctIndex":0,"ayuda":{"pista":"Los dos grupos tienen lo mismo en cantidad. Busca en qué se ven distintos.","pasos":["Dos cosas se pueden diferenciar en la cantidad o en cómo son.","Aquí la cantidad es la misma, así que la diferencia está en otra parte.","Mírales el tamaño, si tienen algo puesto, o si están llenos o vacíos."],"ojo":"Si hay la misma cantidad en los dos, la diferencia NO puede ser la cantidad."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('95a58dc6-7175-58d3-8f97-52cf91ff252d'::uuid, 'multiple_choice', '¿En qué se diferencian estos dos grupos?', '{"options":["Uno tiene más bolas","Uno tiene otro color","Uno tiene otra forma","No se diferencian"],"correctIndex":0,"visual":{"tipo":"comparar","icono":"🔴","lados":[{"etiqueta":"Grupo 1","cantidad":3},{"etiqueta":"Grupo 2","cantidad":5}]},"ayuda":{"pista":"Las dos filas del dibujo son del mismo objeto. Mira cuál llega más lejos.","pasos":["Los dos grupos tienen el mismo dibujo, del mismo color y del mismo tamaño.","Entonces la única diferencia posible es cuántos hay en cada uno.","La fila que llega más lejos es la que tiene más."],"ojo":"Si son del mismo color y forma, la diferencia no puede ser el color ni la forma."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('95a58dc6-7175-58d3-8f97-52cf91ff252d'::uuid, 'multiple_choice', '¿En qué se diferencian estos dos grupos?', '{"options":["Uno tiene más estrellas","Uno tiene otro color","Uno tiene otro tamaño","No se diferencian"],"correctIndex":0,"visual":{"tipo":"comparar","icono":"⭐","lados":[{"etiqueta":"Grupo 1","cantidad":2},{"etiqueta":"Grupo 2","cantidad":6}]},"ayuda":{"pista":"Las dos filas del dibujo son del mismo objeto. Mira cuál llega más lejos.","pasos":["Los dos grupos tienen el mismo dibujo, del mismo color y del mismo tamaño.","Entonces la única diferencia posible es cuántos hay en cada uno.","La fila que llega más lejos es la que tiene más."],"ojo":"Si son del mismo color y forma, la diferencia no puede ser el color ni la forma."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('95a58dc6-7175-58d3-8f97-52cf91ff252d'::uuid, 'multiple_choice', '¿Cuál grupo tiene más?', '{"options":["El grupo 1","El grupo 2","Los dos igual","No se sabe"],"correctIndex":0,"visual":{"tipo":"comparar","icono":"🟦","lados":[{"etiqueta":"Grupo 1","cantidad":4},{"etiqueta":"Grupo 2","cantidad":2}]},"ayuda":{"pista":"Las dos filas del dibujo son del mismo objeto. Mira cuál llega más lejos.","pasos":["Los dos grupos tienen el mismo dibujo, del mismo color y del mismo tamaño.","Entonces la única diferencia posible es cuántos hay en cada uno.","La fila que llega más lejos es la que tiene más."],"ojo":"Si son del mismo color y forma, la diferencia no puede ser el color ni la forma."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('ecf8e0e0-26bd-5acf-8613-914ffe6a1e87'::uuid, 'multiple_choice', 'Sacas agua de la jarra para llenar vasos. En la jarra:', '{"options":["Queda menos agua","Queda más agua","Queda la misma agua","Queda el doble de agua"],"correctIndex":0,"ayuda":{"pista":"Si sacas de un sitio queda menos allí; si echas, queda más.","pasos":["Lo que sale de un lugar tiene que salir de algún lado: del que lo tenía.","Sacar agua de la jarra deja menos agua en la jarra.","Echarle agua al balde deja más agua en el balde."],"ojo":"El agua no desaparece ni aparece: cambia de sitio."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('ecf8e0e0-26bd-5acf-8613-914ffe6a1e87'::uuid, 'multiple_choice', 'Le echas más agua al balde. En el balde:', '{"options":["Hay más agua","Hay menos agua","Queda igual","El agua se seca"],"correctIndex":0,"ayuda":{"pista":"Si sacas de un sitio queda menos allí; si echas, queda más.","pasos":["Lo que sale de un lugar tiene que salir de algún lado: del que lo tenía.","Sacar agua de la jarra deja menos agua en la jarra.","Echarle agua al balde deja más agua en el balde."],"ojo":"El agua no desaparece ni aparece: cambia de sitio."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('ecf8e0e0-26bd-5acf-8613-914ffe6a1e87'::uuid, 'multiple_choice', 'Repartes las galletas del paquete. En el paquete:', '{"options":["Quedan menos","Quedan más","Quedan igual","Se hacen grandes"],"correctIndex":0,"ayuda":{"pista":"Si sacas de un sitio queda menos allí; si echas, queda más.","pasos":["Lo que sale de un lugar tiene que salir de algún lado: del que lo tenía.","Sacar agua de la jarra deja menos agua en la jarra.","Echarle agua al balde deja más agua en el balde."],"ojo":"El agua no desaparece ni aparece: cambia de sitio."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('ecf8e0e0-26bd-5acf-8613-914ffe6a1e87'::uuid, 'multiple_choice', 'Suben más personas al bus. Los puestos libres:', '{"options":["Son menos","Son más","Son los mismos","Son el doble"],"correctIndex":0,"ayuda":{"pista":"Ojo: aquí no preguntan por las personas, preguntan por los puestos LIBRES.","pasos":["En un bus hay un número fijo de puestos: unos ocupados y otros libres.","Si suben más personas, ocupan puestos, así que quedan menos libres.","Si se bajan, dejan puestos, así que quedan más libres."],"ojo":"Cuando una cosa sube, la otra baja. Lee bien por cuál de las dos preguntan."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('ecf8e0e0-26bd-5acf-8613-914ffe6a1e87'::uuid, 'multiple_choice', 'Se bajan personas del bus. Los puestos libres:', '{"options":["Son más","Son menos","Son los mismos","Desaparecen"],"correctIndex":0,"ayuda":{"pista":"Ojo: aquí no preguntan por las personas, preguntan por los puestos LIBRES.","pasos":["En un bus hay un número fijo de puestos: unos ocupados y otros libres.","Si suben más personas, ocupan puestos, así que quedan menos libres.","Si se bajan, dejan puestos, así que quedan más libres."],"ojo":"Cuando una cosa sube, la otra baja. Lee bien por cuál de las dos preguntan."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('ecf8e0e0-26bd-5acf-8613-914ffe6a1e87'::uuid, 'multiple_choice', 'Llegan más niños al salón. Las sillas vacías:', '{"options":["Son menos","Son más","Son las mismas","Se rompen"],"correctIndex":0,"ayuda":{"pista":"Ojo: aquí no preguntan por las personas, preguntan por los puestos LIBRES.","pasos":["En un bus hay un número fijo de puestos: unos ocupados y otros libres.","Si suben más personas, ocupan puestos, así que quedan menos libres.","Si se bajan, dejan puestos, así que quedan más libres."],"ojo":"Cuando una cosa sube, la otra baja. Lee bien por cuál de las dos preguntan."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('ecf8e0e0-26bd-5acf-8613-914ffe6a1e87'::uuid, 'multiple_choice', 'Mientras más crece un árbol, el árbol es:', '{"options":["Más alto","Más bajito","Igual de alto","Más delgado"],"correctIndex":0,"ayuda":{"pista":"Piensa qué le pasa a lo que está alrededor cuando la cosa se hace más grande.","pasos":["Cuando algo crece, ocupa más espacio del que ocupaba antes.","Un árbol que crece queda más alto; un globo que se infla queda más grande.","Y la ropa, que no creció, le queda más apretada al niño que sí creció."],"ojo":"La ropa no encogió: fue el niño el que creció."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('ecf8e0e0-26bd-5acf-8613-914ffe6a1e87'::uuid, 'multiple_choice', 'Mientras más crece un niño, su ropa le queda:', '{"options":["Más apretada","Más grande","Igual","Más suave"],"correctIndex":0,"ayuda":{"pista":"Piensa qué le pasa a lo que está alrededor cuando la cosa se hace más grande.","pasos":["Cuando algo crece, ocupa más espacio del que ocupaba antes.","Un árbol que crece queda más alto; un globo que se infla queda más grande.","Y la ropa, que no creció, le queda más apretada al niño que sí creció."],"ojo":"La ropa no encogió: fue el niño el que creció."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('ecf8e0e0-26bd-5acf-8613-914ffe6a1e87'::uuid, 'multiple_choice', 'Mientras más inflas un globo, se pone:', '{"options":["Más grande","Más pequeño","Igual","Más pesado"],"correctIndex":0,"ayuda":{"pista":"Piensa qué le pasa a lo que está alrededor cuando la cosa se hace más grande.","pasos":["Cuando algo crece, ocupa más espacio del que ocupaba antes.","Un árbol que crece queda más alto; un globo que se infla queda más grande.","Y la ropa, que no creció, le queda más apretada al niño que sí creció."],"ojo":"La ropa no encogió: fue el niño el que creció."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('ecf8e0e0-26bd-5acf-8613-914ffe6a1e87'::uuid, 'multiple_choice', 'Si caminas más rápido, llegas:', '{"options":["Más temprano","Más tarde","A la misma hora","Al día siguiente"],"correctIndex":0,"ayuda":{"pista":"Piensa en el reloj: ir más rápido gasta menos tiempo.","pasos":["Si vas más rápido por el mismo camino, gastas menos tiempo y llegas antes.","Si vas más despacio, gastas más tiempo y llegas después.","Y si el camino es más largo, aunque vayas igual de rápido, te demoras más."],"ojo":"Más rápido y más tiempo no van juntos: cuando una sube, la otra baja."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('ecf8e0e0-26bd-5acf-8613-914ffe6a1e87'::uuid, 'multiple_choice', 'Si caminas más despacio, llegas:', '{"options":["Más tarde","Más temprano","A la misma hora","Nunca"],"correctIndex":0,"ayuda":{"pista":"Piensa en el reloj: ir más rápido gasta menos tiempo.","pasos":["Si vas más rápido por el mismo camino, gastas menos tiempo y llegas antes.","Si vas más despacio, gastas más tiempo y llegas después.","Y si el camino es más largo, aunque vayas igual de rápido, te demoras más."],"ojo":"Más rápido y más tiempo no van juntos: cuando una sube, la otra baja."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('ecf8e0e0-26bd-5acf-8613-914ffe6a1e87'::uuid, 'multiple_choice', 'Si el camino es más largo, te demoras:', '{"options":["Más tiempo","Menos tiempo","El mismo tiempo","Nada"],"correctIndex":0,"ayuda":{"pista":"Piensa en el reloj: ir más rápido gasta menos tiempo.","pasos":["Si vas más rápido por el mismo camino, gastas menos tiempo y llegas antes.","Si vas más despacio, gastas más tiempo y llegas después.","Y si el camino es más largo, aunque vayas igual de rápido, te demoras más."],"ojo":"Más rápido y más tiempo no van juntos: cuando una sube, la otra baja."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('95a58dc6-7175-58d3-8f97-52cf91ff252d'::uuid, 'multiple_choice', 'Pasas agua de la jarra al vaso. ¿Qué pasa?', '{"options":["Baja en la jarra y sube en el vaso","Baja en la jarra y el vaso igual","Sube en la jarra y baja en el vaso","No cambia en ninguno de los dos"],"correctIndex":0,"ayuda":{"pista":"Lo que sale de un lado entra al otro: fíjate que siempre cambian DOS cosas, no una.","pasos":["El agua no aparece ni desaparece: se cambia de sitio.","Entonces donde estaba queda menos, y donde llegó hay más. Las dos cosas cambian a la vez.","Y cambian en la misma cantidad: lo que baja en la jarra es justo lo que sube en el vaso."],"ojo":"Contestar «solo baja en la jarra» se queda a mitad: el agua tuvo que irse para algún lado."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('95a58dc6-7175-58d3-8f97-52cf91ff252d'::uuid, 'multiple_choice', 'Sacas galletas del paquete al plato. ¿Qué pasa?', '{"options":["Bajan del paquete y suben al plato","Bajan del paquete y el plato igual","Suben en el paquete y en el plato","No cambia en ninguno de los dos"],"correctIndex":0,"ayuda":{"pista":"Lo que sale de un lado entra al otro: fíjate que siempre cambian DOS cosas, no una.","pasos":["El agua no aparece ni desaparece: se cambia de sitio.","Entonces donde estaba queda menos, y donde llegó hay más. Las dos cosas cambian a la vez.","Y cambian en la misma cantidad: lo que baja en la jarra es justo lo que sube en el vaso."],"ojo":"Contestar «solo baja en la jarra» se queda a mitad: el agua tuvo que irse para algún lado."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('95a58dc6-7175-58d3-8f97-52cf91ff252d'::uuid, 'multiple_choice', 'Al pasar agua al vaso, el agua que sale de la jarra es:', '{"options":["La misma que entra al vaso","La mitad de la que entra","El doble de la que entra","Ninguna, la jarra queda igual"],"correctIndex":0,"ayuda":{"pista":"Lo que sale de un lado entra al otro: fíjate que siempre cambian DOS cosas, no una.","pasos":["El agua no aparece ni desaparece: se cambia de sitio.","Entonces donde estaba queda menos, y donde llegó hay más. Las dos cosas cambian a la vez.","Y cambian en la misma cantidad: lo que baja en la jarra es justo lo que sube en el vaso."],"ojo":"Contestar «solo baja en la jarra» se queda a mitad: el agua tuvo que irse para algún lado."}}'::jsonb, 10);
