insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('243488ab-c997-5258-81fd-850910fa3e8a'::uuid, 'multiple_choice', 'En 3 + ? = 4 + ?, ¿cuántas parejas sirven?', '{"options":["Muchas","Solo una","Ninguna","Solo dos"],"correctIndex":0,"ayuda":{"pista":"No busques UNA respuesta: mira si cambiando un lado puedes arreglar el otro.","pasos":["Los dos lados tienen que valer lo mismo, pero nadie dijo cuánto.","Si eliges un número para un hueco, siempre puedes elegir el del otro para que empaten.","Por eso no hay una sola solución: hay muchísimas, y todas valen."],"ojo":"Que haya varias respuestas correctas no significa que la pregunta esté mala."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('243488ab-c997-5258-81fd-850910fa3e8a'::uuid, 'multiple_choice', 'Si el lado izquierdo crece 2, el derecho tiene que:', '{"options":["Crecer 2 también","Quedarse igual","Bajar 2","Crecer 4"],"correctIndex":0,"ayuda":{"pista":"No busques UNA respuesta: mira si cambiando un lado puedes arreglar el otro.","pasos":["Los dos lados tienen que valer lo mismo, pero nadie dijo cuánto.","Si eliges un número para un hueco, siempre puedes elegir el del otro para que empaten.","Por eso no hay una sola solución: hay muchísimas, y todas valen."],"ojo":"Que haya varias respuestas correctas no significa que la pregunta esté mala."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('243488ab-c997-5258-81fd-850910fa3e8a'::uuid, 'multiple_choice', 'En 5 + ? = 2 + ?, el hueco de la derecha tiene que ser:', '{"options":["3 más que el de la izquierda","Igual al de la izquierda","3 menos que el de la izquierda","Cualquier número"],"correctIndex":0,"ayuda":{"pista":"No busques UNA respuesta: mira si cambiando un lado puedes arreglar el otro.","pasos":["Los dos lados tienen que valer lo mismo, pero nadie dijo cuánto.","Si eliges un número para un hueco, siempre puedes elegir el del otro para que empaten.","Por eso no hay una sola solución: hay muchísimas, y todas valen."],"ojo":"Que haya varias respuestas correctas no significa que la pregunta esté mala."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2450e3d3-7fa3-5976-8d7b-30d3d63d9fdb'::uuid, 'multiple_choice', 'La caja pesa igual que 3 libros, y 3 libros igual que 6 vasos.', '{"options":["La caja pesa igual que 6 vasos","La caja pesa más que 6 vasos","La caja pesa menos que 6 vasos","No se puede saber"],"correctIndex":0,"ayuda":{"pista":"Las dos frases comparten algo. Ese algo del medio es el puente entre las puntas.","pasos":["La primera frase compara la primera cosa con la del medio, y son iguales.","La segunda compara la del medio con la última, y también son iguales.","Si las dos puntas valen igual que la del medio, valen igual entre ellas."],"ojo":"No hace falta comparar las puntas directamente: la del medio ya lo dijo."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2450e3d3-7fa3-5976-8d7b-30d3d63d9fdb'::uuid, 'multiple_choice', 'Ana mide igual que Luis, y Luis mide igual que Sara.', '{"options":["Ana mide igual que Sara","Ana mide más que Sara","Ana mide menos que Sara","No se puede saber"],"correctIndex":0,"ayuda":{"pista":"Las dos frases comparten algo. Ese algo del medio es el puente entre las puntas.","pasos":["La primera frase compara la primera cosa con la del medio, y son iguales.","La segunda compara la del medio con la última, y también son iguales.","Si las dos puntas valen igual que la del medio, valen igual entre ellas."],"ojo":"No hace falta comparar las puntas directamente: la del medio ya lo dijo."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2450e3d3-7fa3-5976-8d7b-30d3d63d9fdb'::uuid, 'multiple_choice', 'La cinta roja mide igual que la azul, y la azul que la verde.', '{"options":["La roja mide igual que la verde","La roja mide más que la verde","La roja mide menos que la verde","No se puede saber"],"correctIndex":0,"ayuda":{"pista":"Las dos frases comparten algo. Ese algo del medio es el puente entre las puntas.","pasos":["La primera frase compara la primera cosa con la del medio, y son iguales.","La segunda compara la del medio con la última, y también son iguales.","Si las dos puntas valen igual que la del medio, valen igual entre ellas."],"ojo":"No hace falta comparar las puntas directamente: la del medio ya lo dijo."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2450e3d3-7fa3-5976-8d7b-30d3d63d9fdb'::uuid, 'multiple_choice', 'La cinta roja es más larga que la azul, y la azul que la verde.', '{"options":["La cinta roja","La cinta azul","La cinta verde","Las tres miden igual"],"correctIndex":0,"ayuda":{"pista":"Ponlas en fila de mayor a menor siguiendo las dos frases, y mira quién queda de primera.","pasos":["La primera frase te dice quién le gana a quién entre las dos primeras.","La segunda hace lo mismo con la del medio y la última.","Armando la fila queda claro: la primera le gana a la del medio, y la del medio a la última."],"ojo":"Aquí no son iguales sino que una le gana a la otra, pero la cadena funciona igual."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2450e3d3-7fa3-5976-8d7b-30d3d63d9fdb'::uuid, 'multiple_choice', 'Ana es más alta que Luis, y Luis es más alto que Sara.', '{"options":["Ana es la más alta","Luis es el más alto","Sara es la más alta","Los tres miden igual"],"correctIndex":0,"ayuda":{"pista":"Ponlas en fila de mayor a menor siguiendo las dos frases, y mira quién queda de primera.","pasos":["La primera frase te dice quién le gana a quién entre las dos primeras.","La segunda hace lo mismo con la del medio y la última.","Armando la fila queda claro: la primera le gana a la del medio, y la del medio a la última."],"ojo":"Aquí no son iguales sino que una le gana a la otra, pero la cadena funciona igual."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2450e3d3-7fa3-5976-8d7b-30d3d63d9fdb'::uuid, 'multiple_choice', 'La caja pesa más que el libro, y el libro más que el lápiz.', '{"options":["La caja es la más pesada","El libro es el más pesado","El lápiz es el más pesado","Los tres pesan igual"],"correctIndex":0,"ayuda":{"pista":"Ponlas en fila de mayor a menor siguiendo las dos frases, y mira quién queda de primera.","pasos":["La primera frase te dice quién le gana a quién entre las dos primeras.","La segunda hace lo mismo con la del medio y la última.","Armando la fila queda claro: la primera le gana a la del medio, y la del medio a la última."],"ojo":"Aquí no son iguales sino que una le gana a la otra, pero la cadena funciona igual."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('243488ab-c997-5258-81fd-850910fa3e8a'::uuid, 'multiple_choice', 'El signo = dice que los dos lados:', '{"options":["Valen igual","Se suman","Son distintos","Se restan"],"correctIndex":0,"ayuda":{"pista":"El signo = es una balanza: dice que los dos lados pesan lo mismo.","pasos":["El signo = no significa «aquí va la respuesta». Significa «vale lo mismo que».","En 3 + 2 = 5 está diciendo que 3 + 2 y 5 son la misma cantidad escrita de dos maneras.","Por eso solo se escribe = cuando los dos lados valen igual."],"ojo":"Es el error más común de todos: creer que = es la orden de calcular."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('243488ab-c997-5258-81fd-850910fa3e8a'::uuid, 'multiple_choice', 'Si los dos lados valen lo mismo, se escribe:', '{"options":["El signo =","El signo +","El signo −","Nada"],"correctIndex":0,"ayuda":{"pista":"El signo = es una balanza: dice que los dos lados pesan lo mismo.","pasos":["El signo = no significa «aquí va la respuesta». Significa «vale lo mismo que».","En 3 + 2 = 5 está diciendo que 3 + 2 y 5 son la misma cantidad escrita de dos maneras.","Por eso solo se escribe = cuando los dos lados valen igual."],"ojo":"Es el error más común de todos: creer que = es la orden de calcular."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('243488ab-c997-5258-81fd-850910fa3e8a'::uuid, 'multiple_choice', 'En 3 + 2 = 5, el signo = dice que:', '{"options":["3 + 2 vale lo mismo que 5","3 + 2 es mayor que 5","3 + 2 es menor que 5","3 + 2 hay que restarlo"],"correctIndex":0,"ayuda":{"pista":"El signo = es una balanza: dice que los dos lados pesan lo mismo.","pasos":["El signo = no significa «aquí va la respuesta». Significa «vale lo mismo que».","En 3 + 2 = 5 está diciendo que 3 + 2 y 5 son la misma cantidad escrita de dos maneras.","Por eso solo se escribe = cuando los dos lados valen igual."],"ojo":"Es el error más común de todos: creer que = es la orden de calcular."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('243488ab-c997-5258-81fd-850910fa3e8a'::uuid, 'multiple_choice', 'En 4 + ? = 4 + 6, el número que falta es:', '{"options":["Igual a 6","Mayor que 6","Menor que 6","Cualquiera"],"correctIndex":0,"ayuda":{"pista":"Si los dos lados tienen el mismo número repetido, el que falta también es igual al que sobra.","pasos":["Mira los dos lados y busca el número que se repite en los dos.","Si ese número está en los dos lados, se equilibra solo y no hay que hacerle nada.","Entonces lo que falta tiene que ser igual al número que quedó del otro lado."],"ojo":"Aquí no hay que sumar nada: basta con comparar los dos lados."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('243488ab-c997-5258-81fd-850910fa3e8a'::uuid, 'multiple_choice', 'En 7 + ? = 7 + 2, el número que falta es:', '{"options":["Igual a 2","Mayor que 2","Menor que 2","Cualquiera"],"correctIndex":0,"ayuda":{"pista":"Si los dos lados tienen el mismo número repetido, el que falta también es igual al que sobra.","pasos":["Mira los dos lados y busca el número que se repite en los dos.","Si ese número está en los dos lados, se equilibra solo y no hay que hacerle nada.","Entonces lo que falta tiene que ser igual al número que quedó del otro lado."],"ojo":"Aquí no hay que sumar nada: basta con comparar los dos lados."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('243488ab-c997-5258-81fd-850910fa3e8a'::uuid, 'multiple_choice', 'En ? + 5 = 3 + 5, el número que falta es:', '{"options":["Igual a 3","Mayor que 3","Menor que 3","Cualquiera"],"correctIndex":0,"ayuda":{"pista":"Si los dos lados tienen el mismo número repetido, el que falta también es igual al que sobra.","pasos":["Mira los dos lados y busca el número que se repite en los dos.","Si ese número está en los dos lados, se equilibra solo y no hay que hacerle nada.","Entonces lo que falta tiene que ser igual al número que quedó del otro lado."],"ojo":"Aquí no hay que sumar nada: basta con comparar los dos lados."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2450e3d3-7fa3-5976-8d7b-30d3d63d9fdb'::uuid, 'multiple_choice', 'Mira las dos igualdades. ¿A qué más es igual 3 + 4?', '{"options":["5 + 2","5 − 2","3 + 2","7 + 7"],"correctIndex":0,"operation":"3 + 4 = 7   y   7 = 5 + 2","ayuda":{"pista":"Las dos igualdades comparten un número. Ese número es el puente entre las dos.","pasos":["La primera igualdad dice cuánto vale la suma de la izquierda.","La segunda dice que ese mismo resultado vale igual que otra suma.","Entonces las dos sumas valen lo mismo, aunque nunca las hayan escrito juntas."],"ojo":"Si dos cosas valen igual que una tercera, valen igual entre ellas."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2450e3d3-7fa3-5976-8d7b-30d3d63d9fdb'::uuid, 'multiple_choice', 'Mira las dos igualdades. ¿A qué más es igual 2 + 6?', '{"options":["4 + 4","4 − 4","2 + 4","8 + 8"],"correctIndex":0,"operation":"2 + 6 = 8   y   8 = 4 + 4","ayuda":{"pista":"Las dos igualdades comparten un número. Ese número es el puente entre las dos.","pasos":["La primera igualdad dice cuánto vale la suma de la izquierda.","La segunda dice que ese mismo resultado vale igual que otra suma.","Entonces las dos sumas valen lo mismo, aunque nunca las hayan escrito juntas."],"ojo":"Si dos cosas valen igual que una tercera, valen igual entre ellas."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2450e3d3-7fa3-5976-8d7b-30d3d63d9fdb'::uuid, 'multiple_choice', 'Mira las dos igualdades. ¿A qué más es igual 1 + 5?', '{"options":["3 + 3","3 − 3","1 + 3","6 + 6"],"correctIndex":0,"operation":"1 + 5 = 6   y   6 = 3 + 3","ayuda":{"pista":"Las dos igualdades comparten un número. Ese número es el puente entre las dos.","pasos":["La primera igualdad dice cuánto vale la suma de la izquierda.","La segunda dice que ese mismo resultado vale igual que otra suma.","Entonces las dos sumas valen lo mismo, aunque nunca las hayan escrito juntas."],"ojo":"Si dos cosas valen igual que una tercera, valen igual entre ellas."}}'::jsonb, 10);
