insert into learning_evidences (id, dba_id, num, texto) select '92a5555e-9098-5e67-85a4-781b9230ea04'::uuid, d.id, 4, 'Comunica los resultados respondiendo preguntas tales como: ¿cuántos hay en total?, ¿cuántos hay de cada dato?, ¿cuál es el dato que más se repite?, ¿cuál es el dato que menos aparece?' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 10;
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('775f5de5-d7d7-5c45-8fa1-1461f72a6173'::uuid, 'multiple_choice', 'Cada chocolate es 1 niño. ¿Cuántos lo quieren?', '{"options":["4","3","5","8"],"correctIndex":0,"visual":{"tipo":"contar","icono":"🍫","cantidad":4},"ayuda":{"pista":"Cada dibujo vale 1 niño. Cuenta los dibujos, uno por uno.","pasos":["En un pictograma, cada dibujo representa a alguien o a algo.","Aquí cada dibujo es un niño, así que la cantidad de dibujos es la cantidad de niños.","Cuéntalos tocándolos con el dedo para no repetir ni saltarte ninguno."],"ojo":"No hay que sumar ni multiplicar: cada dibujo vale exactamente uno."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('775f5de5-d7d7-5c45-8fa1-1461f72a6173'::uuid, 'multiple_choice', 'Cada fresa es 1 niño. ¿Cuántos la quieren?', '{"options":["6","5","7","12"],"correctIndex":0,"visual":{"tipo":"contar","icono":"🍓","cantidad":6},"ayuda":{"pista":"Cada dibujo vale 1 niño. Cuenta los dibujos, uno por uno.","pasos":["En un pictograma, cada dibujo representa a alguien o a algo.","Aquí cada dibujo es un niño, así que la cantidad de dibujos es la cantidad de niños.","Cuéntalos tocándolos con el dedo para no repetir ni saltarte ninguno."],"ojo":"No hay que sumar ni multiplicar: cada dibujo vale exactamente uno."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('775f5de5-d7d7-5c45-8fa1-1461f72a6173'::uuid, 'multiple_choice', 'Cada banano es 1 niño. ¿Cuántos lo quieren?', '{"options":["3","2","4","6"],"correctIndex":0,"visual":{"tipo":"contar","icono":"🍌","cantidad":3},"ayuda":{"pista":"Cada dibujo vale 1 niño. Cuenta los dibujos, uno por uno.","pasos":["En un pictograma, cada dibujo representa a alguien o a algo.","Aquí cada dibujo es un niño, así que la cantidad de dibujos es la cantidad de niños.","Cuéntalos tocándolos con el dedo para no repetir ni saltarte ninguno."],"ojo":"No hay que sumar ni multiplicar: cada dibujo vale exactamente uno."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('775f5de5-d7d7-5c45-8fa1-1461f72a6173'::uuid, 'multiple_choice', 'Cada dibujo es 1 perro. ¿Cuántos perros hay?', '{"options":["6","5","7","12"],"correctIndex":0,"visual":{"tipo":"contar","icono":"🐶","cantidad":6},"ayuda":{"pista":"Cada dibujo vale 1. Cuéntalos tocándolos con el dedo.","pasos":["Un pictograma cuenta con dibujos en vez de con números.","Como cada dibujo vale 1, la respuesta es cuántos dibujos hay.","Cuenta despacio y toca cada uno para no contar ninguno dos veces."],"ojo":"Contar de dos en dos aquí da el doble: cada dibujo es uno, no dos."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('775f5de5-d7d7-5c45-8fa1-1461f72a6173'::uuid, 'multiple_choice', 'Cada dibujo es 1 gato. ¿Cuántos gatos hay?', '{"options":["5","4","6","10"],"correctIndex":0,"visual":{"tipo":"contar","icono":"🐱","cantidad":5},"ayuda":{"pista":"Cada dibujo vale 1. Cuéntalos tocándolos con el dedo.","pasos":["Un pictograma cuenta con dibujos en vez de con números.","Como cada dibujo vale 1, la respuesta es cuántos dibujos hay.","Cuenta despacio y toca cada uno para no contar ninguno dos veces."],"ojo":"Contar de dos en dos aquí da el doble: cada dibujo es uno, no dos."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('775f5de5-d7d7-5c45-8fa1-1461f72a6173'::uuid, 'multiple_choice', 'Cada dibujo es 1 pájaro. ¿Cuántos pájaros hay?', '{"options":["7","6","8","14"],"correctIndex":0,"visual":{"tipo":"contar","icono":"🐦","cantidad":7},"ayuda":{"pista":"Cada dibujo vale 1. Cuéntalos tocándolos con el dedo.","pasos":["Un pictograma cuenta con dibujos en vez de con números.","Como cada dibujo vale 1, la respuesta es cuántos dibujos hay.","Cuenta despacio y toca cada uno para no contar ninguno dos veces."],"ojo":"Contar de dos en dos aquí da el doble: cada dibujo es uno, no dos."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('88cfc42a-4bc4-5265-870b-c830ec49f5c1'::uuid, 'multiple_choice', '5 niños quieren fresa. En el pictograma dibujas:', '{"options":["5 fresas","1 fresa","5 niños y 5 fresas","Nada"],"correctIndex":0,"ayuda":{"pista":"Sin escala, cada dibujo vale UNO. Tantos dibujos como cosas hay.","pasos":["Un pictograma sin escala cambia cada cosa por un dibujo, uno por uno.","Si cinco niños quieren fresa, dibujas cinco fresas: ni una, ni diez.","Y cada dato va en su propia fila, con su nombre al lado, para poder comparar las filas."],"ojo":"No se dibuja el niño Y la fresa: sería contar dos veces lo mismo."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('88cfc42a-4bc4-5265-870b-c830ec49f5c1'::uuid, 'multiple_choice', 'En el dibujo de la votación, cada dibujito vale:', '{"options":["Uno","Dos","Cinco","Diez"],"correctIndex":0,"ayuda":{"pista":"Sin escala, cada dibujo vale UNO. Tantos dibujos como cosas hay.","pasos":["Un pictograma sin escala cambia cada cosa por un dibujo, uno por uno.","Si cinco niños quieren fresa, dibujas cinco fresas: ni una, ni diez.","Y cada dato va en su propia fila, con su nombre al lado, para poder comparar las filas."],"ojo":"No se dibuja el niño Y la fresa: sería contar dos veces lo mismo."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('88cfc42a-4bc4-5265-870b-c830ec49f5c1'::uuid, 'multiple_choice', 'En la tabla, cada sabor de helado va:', '{"options":["En su propia fila","Todos en una fila","Sin nombre","En cualquier fila"],"correctIndex":0,"ayuda":{"pista":"Sin escala, cada dibujo vale UNO. Tantos dibujos como cosas hay.","pasos":["Un pictograma sin escala cambia cada cosa por un dibujo, uno por uno.","Si cinco niños quieren fresa, dibujas cinco fresas: ni una, ni diez.","Y cada dato va en su propia fila, con su nombre al lado, para poder comparar las filas."],"ojo":"No se dibuja el niño Y la fresa: sería contar dos veces lo mismo."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('88cfc42a-4bc4-5265-870b-c830ec49f5c1'::uuid, 'multiple_choice', 'En una tabla de conteo, las rayitas sirven para:', '{"options":["Contar cuántos hay","Saber quién votó","Saber qué día fue","Adornar la tabla"],"correctIndex":0,"ayuda":{"pista":"Una rayita es una anotación: cada vez que pasa algo, haces una.","pasos":["La tabla de conteo sirve para ir anotando mientras cuentas, sin perder la cuenta.","Cada vez que alguien vota o que aparece algo, haces UNA rayita.","Al final cuentas las rayitas y ese número es el total."],"ojo":"Cada rayita vale uno. Cinco rayitas son cinco, no cinco grupos."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('88cfc42a-4bc4-5265-870b-c830ec49f5c1'::uuid, 'multiple_choice', 'Si haces 5 rayitas en la tabla, eso quiere decir:', '{"options":["Que hay 5","Que hay 1","Que hay 10","Que no hay"],"correctIndex":0,"ayuda":{"pista":"Una rayita es una anotación: cada vez que pasa algo, haces una.","pasos":["La tabla de conteo sirve para ir anotando mientras cuentas, sin perder la cuenta.","Cada vez que alguien vota o que aparece algo, haces UNA rayita.","Al final cuentas las rayitas y ese número es el total."],"ojo":"Cada rayita vale uno. Cinco rayitas son cinco, no cinco grupos."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('88cfc42a-4bc4-5265-870b-c830ec49f5c1'::uuid, 'multiple_choice', 'Para anotar cada voto en la tabla, haces:', '{"options":["Una rayita","Un círculo grande","Una letra","Nada"],"correctIndex":0,"ayuda":{"pista":"Una rayita es una anotación: cada vez que pasa algo, haces una.","pasos":["La tabla de conteo sirve para ir anotando mientras cuentas, sin perder la cuenta.","Cada vez que alguien vota o que aparece algo, haces UNA rayita.","Al final cuentas las rayitas y ese número es el total."],"ojo":"Cada rayita vale uno. Cinco rayitas son cinco, no cinco grupos."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e301d21a-6553-5c45-8110-f4c2b0c92139'::uuid, 'multiple_choice', 'En una encuesta de mascota favorita se cuenta:', '{"options":["Cuántos eligen cada mascota","Cuánto pesa cada mascota","Cuántos años tiene cada niño","Cuántas mascotas hay en casa"],"correctIndex":0,"ayuda":{"pista":"En una encuesta se cuenta CUÁNTOS eligieron cada respuesta.","pasos":["Una encuesta empieza con una pregunta y varias respuestas posibles.","Cada persona elige una, y lo que se anota es cuántas personas eligieron cada cual.","Al final se compara: la que más eligieron es la favorita del grupo."],"ojo":"No se cuenta el tamaño ni la edad de nadie: se cuentan las respuestas."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e301d21a-6553-5c45-8110-f4c2b0c92139'::uuid, 'multiple_choice', 'En una encuesta de color favorito se cuenta:', '{"options":["Cuántos eligen cada color","Cuántos colores existen","Cuántos años tiene cada niño","Cuánto cuesta cada color"],"correctIndex":0,"ayuda":{"pista":"En una encuesta se cuenta CUÁNTOS eligieron cada respuesta.","pasos":["Una encuesta empieza con una pregunta y varias respuestas posibles.","Cada persona elige una, y lo que se anota es cuántas personas eligieron cada cual.","Al final se compara: la que más eligieron es la favorita del grupo."],"ojo":"No se cuenta el tamaño ni la edad de nadie: se cuentan las respuestas."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e301d21a-6553-5c45-8110-f4c2b0c92139'::uuid, 'multiple_choice', 'En una encuesta de deporte favorito se cuenta:', '{"options":["Cuántos eligen cada deporte","Cuántos deportes existen","Cuánto corre cada niño","Cuánto dura cada deporte"],"correctIndex":0,"ayuda":{"pista":"En una encuesta se cuenta CUÁNTOS eligieron cada respuesta.","pasos":["Una encuesta empieza con una pregunta y varias respuestas posibles.","Cada persona elige una, y lo que se anota es cuántas personas eligieron cada cual.","Al final se compara: la que más eligieron es la favorita del grupo."],"ojo":"No se cuenta el tamaño ni la edad de nadie: se cuentan las respuestas."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e301d21a-6553-5c45-8110-f4c2b0c92139'::uuid, 'multiple_choice', 'Para saber la fruta preferida del salón, preguntas a:', '{"options":["A todos los del salón","A un solo niño del salón","Solo a la profesora","A nadie del salón"],"correctIndex":0,"ayuda":{"pista":"Si quieres saber lo que piensa el curso entero, tienes que preguntarle al curso entero.","pasos":["Una encuesta habla del grupo al que se le preguntó, no de otro.","Si le preguntas a todo el curso, el resultado dice lo que piensa el curso.","Si le preguntas solo a dos, el resultado dice lo que piensan esos dos y nada más."],"ojo":"Preguntarle a pocos no está mal: lo que está mal es creer que eso habla de todos."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e301d21a-6553-5c45-8110-f4c2b0c92139'::uuid, 'multiple_choice', 'Para saber el color favorito del curso, preguntas a:', '{"options":["A todo el curso","A un solo niño del curso","Solo a la profesora","A nadie del curso"],"correctIndex":0,"ayuda":{"pista":"Si quieres saber lo que piensa el curso entero, tienes que preguntarle al curso entero.","pasos":["Una encuesta habla del grupo al que se le preguntó, no de otro.","Si le preguntas a todo el curso, el resultado dice lo que piensa el curso.","Si le preguntas solo a dos, el resultado dice lo que piensan esos dos y nada más."],"ojo":"Preguntarle a pocos no está mal: lo que está mal es creer que eso habla de todos."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e301d21a-6553-5c45-8110-f4c2b0c92139'::uuid, 'multiple_choice', 'Si solo le preguntas a dos niños, el resultado dice:', '{"options":["Lo que piensan esos dos niños","Lo que piensan todos los niños","Lo que piensan los otros niños","Lo que piensan las profesoras"],"correctIndex":0,"ayuda":{"pista":"Si quieres saber lo que piensa el curso entero, tienes que preguntarle al curso entero.","pasos":["Una encuesta habla del grupo al que se le preguntó, no de otro.","Si le preguntas a todo el curso, el resultado dice lo que piensa el curso.","Si le preguntas solo a dos, el resultado dice lo que piensan esos dos y nada más."],"ojo":"Preguntarle a pocos no está mal: lo que está mal es creer que eso habla de todos."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('92a5555e-9098-5e67-85a4-781b9230ea04'::uuid, 'multiple_choice', 'Votamos el color favorito. ¿Cuál ganó?', '{"options":["Azul","Rojo","Verde","Hubo empate"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Rojo","valor":3},{"etiqueta":"Azul","valor":5},{"etiqueta":"Verde","valor":2}]},"ayuda":{"pista":"El que ganó es el de la barra más larga. Mira el dibujo antes de contar.","pasos":["Cada barra muestra cuántos votos tuvo cada opción.","La barra más larga es la que más votos tuvo: esa ganó.","Si no se ve claro, mira el número que hay al final de cada barra."],"ojo":"No importa cuál te guste más a ti: la que gana es la que más votos sacó."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('92a5555e-9098-5e67-85a4-781b9230ea04'::uuid, 'multiple_choice', 'En la votación de colores, ¿cuál ganó?', '{"options":["Rojo","Azul","Verde","Hubo empate"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Rojo","valor":6},{"etiqueta":"Azul","valor":2},{"etiqueta":"Verde","valor":4}]},"ayuda":{"pista":"El que ganó es el de la barra más larga. Mira el dibujo antes de contar.","pasos":["Cada barra muestra cuántos votos tuvo cada opción.","La barra más larga es la que más votos tuvo: esa ganó.","Si no se ve claro, mira el número que hay al final de cada barra."],"ojo":"No importa cuál te guste más a ti: la que gana es la que más votos sacó."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('92a5555e-9098-5e67-85a4-781b9230ea04'::uuid, 'multiple_choice', 'Votamos el animal favorito. ¿Cuál ganó?', '{"options":["Hubo empate","Perro","Gato","Pez"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Perro","valor":7},{"etiqueta":"Gato","valor":7},{"etiqueta":"Pez","valor":1}]},"ayuda":{"pista":"El que ganó es el de la barra más larga. Mira el dibujo antes de contar.","pasos":["Cada barra muestra cuántos votos tuvo cada opción.","La barra más larga es la que más votos tuvo: esa ganó.","Si no se ve claro, mira el número que hay al final de cada barra."],"ojo":"No importa cuál te guste más a ti: la que gana es la que más votos sacó."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('92a5555e-9098-5e67-85a4-781b9230ea04'::uuid, 'multiple_choice', 'Votamos el color favorito. ¿Cuál tuvo menos?', '{"options":["Verde","Rojo","Azul","Todos igual"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Rojo","valor":3},{"etiqueta":"Azul","valor":5},{"etiqueta":"Verde","valor":2}]},"ayuda":{"pista":"El que tuvo menos es el de la barra MÁS CORTA.","pasos":["Cada barra dice cuántos votos tuvo esa opción.","La barra más corta es la que menos votos sacó.","Compara las tres y quédate con la más pequeña."],"ojo":"Aquí piden la que tuvo MENOS. Contestar con la ganadora es el error de siempre."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('92a5555e-9098-5e67-85a4-781b9230ea04'::uuid, 'multiple_choice', 'Votamos el animal favorito. ¿Cuál tuvo menos?', '{"options":["Pez","Perro","Gato","Todos igual"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Perro","valor":4},{"etiqueta":"Gato","valor":7},{"etiqueta":"Pez","valor":1}]},"ayuda":{"pista":"El que tuvo menos es el de la barra MÁS CORTA.","pasos":["Cada barra dice cuántos votos tuvo esa opción.","La barra más corta es la que menos votos sacó.","Compara las tres y quédate con la más pequeña."],"ojo":"Aquí piden la que tuvo MENOS. Contestar con la ganadora es el error de siempre."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('92a5555e-9098-5e67-85a4-781b9230ea04'::uuid, 'multiple_choice', 'Votamos el deporte favorito. ¿Cuál tuvo menos?', '{"options":["Natación","Fútbol","Ciclismo","Todos igual"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Fútbol","valor":8},{"etiqueta":"Natación","valor":3},{"etiqueta":"Ciclismo","valor":5}]},"ayuda":{"pista":"El que tuvo menos es el de la barra MÁS CORTA.","pasos":["Cada barra dice cuántos votos tuvo esa opción.","La barra más corta es la que menos votos sacó.","Compara las tres y quédate con la más pequeña."],"ojo":"Aquí piden la que tuvo MENOS. Contestar con la ganadora es el error de siempre."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('92a5555e-9098-5e67-85a4-781b9230ea04'::uuid, 'multiple_choice', 'Votamos el color. ¿Cuántos niños votaron en total?', '{"options":["10","8","9","11"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Rojo","valor":3},{"etiqueta":"Azul","valor":5},{"etiqueta":"Verde","valor":2}]},"ayuda":{"pista":"El total son todos los votos juntos: hay que sumar las tres barras.","pasos":["Cada barra dice cuántos votaron por esa opción.","Como cada niño votó una sola vez, todos los votos juntos son todos los niños.","Súmalos de a dos: primero dos barras, y a ese resultado le sumas la tercera."],"ojo":"El total no es la barra más larga: es la suma de todas."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('92a5555e-9098-5e67-85a4-781b9230ea04'::uuid, 'multiple_choice', 'Votamos el animal. ¿Cuántos niños respondieron?', '{"options":["12","11","10","13"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Perro","valor":4},{"etiqueta":"Gato","valor":7},{"etiqueta":"Pez","valor":1}]},"ayuda":{"pista":"El total son todos los votos juntos: hay que sumar las tres barras.","pasos":["Cada barra dice cuántos votaron por esa opción.","Como cada niño votó una sola vez, todos los votos juntos son todos los niños.","Súmalos de a dos: primero dos barras, y a ese resultado le sumas la tercera."],"ojo":"El total no es la barra más larga: es la suma de todas."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('92a5555e-9098-5e67-85a4-781b9230ea04'::uuid, 'multiple_choice', 'Votamos la fruta. ¿Cuántos niños votaron en total?', '{"options":["12","10","11","13"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Mango","valor":6},{"etiqueta":"Piña","valor":2},{"etiqueta":"Mora","valor":4}]},"ayuda":{"pista":"El total son todos los votos juntos: hay que sumar las tres barras.","pasos":["Cada barra dice cuántos votaron por esa opción.","Como cada niño votó una sola vez, todos los votos juntos son todos los niños.","Súmalos de a dos: primero dos barras, y a ese resultado le sumas la tercera."],"ojo":"El total no es la barra más larga: es la suma de todas."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('92a5555e-9098-5e67-85a4-781b9230ea04'::uuid, 'multiple_choice', '¿Cuántos niños MÁS prefieren mango que papaya?', '{"options":["5","9","4","2"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Mango","valor":7},{"etiqueta":"Papaya","valor":2}]},"ayuda":{"pista":"«Cuántos MÁS» pregunta por la diferencia: se resta la barra corta de la larga.","pasos":["Mira las dos barras que te nombran y fíjate cuál es más larga.","La pregunta es cuánto le sobra a la larga por encima de la corta.","Eso se averigua restando el número pequeño del grande."],"ojo":"No es cuántos votaron en total: es cuántos de diferencia hay entre las dos."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('92a5555e-9098-5e67-85a4-781b9230ea04'::uuid, 'multiple_choice', '¿Cuántos niños MÁS prefieren gato que pez?', '{"options":["6","8","5","1"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Gato","valor":7},{"etiqueta":"Pez","valor":1}]},"ayuda":{"pista":"«Cuántos MÁS» pregunta por la diferencia: se resta la barra corta de la larga.","pasos":["Mira las dos barras que te nombran y fíjate cuál es más larga.","La pregunta es cuánto le sobra a la larga por encima de la corta.","Eso se averigua restando el número pequeño del grande."],"ojo":"No es cuántos votaron en total: es cuántos de diferencia hay entre las dos."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('92a5555e-9098-5e67-85a4-781b9230ea04'::uuid, 'multiple_choice', '¿Cuántos niños MÁS prefieren fútbol que natación?', '{"options":["5","11","4","3"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Fútbol","valor":8},{"etiqueta":"Natación","valor":3}]},"ayuda":{"pista":"«Cuántos MÁS» pregunta por la diferencia: se resta la barra corta de la larga.","pasos":["Mira las dos barras que te nombran y fíjate cuál es más larga.","La pregunta es cuánto le sobra a la larga por encima de la corta.","Eso se averigua restando el número pequeño del grande."],"ojo":"No es cuántos votaron en total: es cuántos de diferencia hay entre las dos."}}'::jsonb, 10);
